'Units_Guide_Note' => 'እንደ «መሰረታዊ መለኪያ» መመረጥ የሚችሉት መሰረታዊ መለኪያዎች ብቻ ናቸው፤ ንዑስ መለኪያዎች እየተጠቀሙበት ያለ መለኪያ ሊሰረዝ አይችልም።',

