'Payment_Amounts_Help' => 'የተከፈለ መጠን ቀሪ ሂሳቡን ያወራርዳል እና ያልተከፈለውን ቀሪ ይቀንሳል። የተቀበሉት መጠን የተሰጠው ጥሬ ገንዘብ ነው፤ የሚመለሰውን መልስ ለማስላት ብቻ ያገለግላል፣ ያልተከፈለውን ቀሪ አይቀይርም።',

