'Show_Items_Tax_Desc' => 'የእያንዳንዱ ምርት የራሱ ግብር ድምር፣ እንደ «የዕቃዎች ጠቅላላ ግብር» መስመር ይታተማል። ሲነቃ ንዑስ ድምሩ እነዚህን ግብሮች ሳይጨምር ይታያል።',
'Show_Discount_Desc' => 'ለሙሉ ሽያጩ የሚተገበር ቅናሽ (የነጥብ ቅናሽን ጨምሮ)፣ በጠቅላላ ድምሮች ውስጥ እንደ ራሱ መስመር ይታተማል።',
'Show_Product_Discount_Desc' => 'የእያንዳንዱ ምርት የራሱ ቅናሽ፣ በዕቃዎች ዝርዝር ውስጥ ከዚያ ምርት ስር ይታተማል።',

