'Receipt_Font_Size' => 'የደረሰኝ ፊደል መጠን (px)',
'Receipt_Font_Size_Desc' => 'በሙሉ ደረሰኙ ላይ ያለ የጽሑፍ መጠን፣ ከ8 እስከ 24 ፒክሰል። ነባሪውን መጠን ለመያዝ ባዶ ይተዉት።',
