'Additional_Information' => 'ተጨማሪ መረጃ',
'Warehouses_Tab_Help' => 'መጋዘኖችዎን (ሱቆች/ቅርንጫፎች) ያስተዳድሩ። እያንዳንዱ መጋዘን የራሱን ክምችት ይይዛል፤ እያንዳንዱ ሰነድ — ሽያጮች፣ ግዢዎች፣ ዝውውሮች፣ ማስተካከያዎች — ከአንዱ ጋር ተያይዞ ይመዘገባል።',
'Warehouse_Locations_Tab_Help' => 'በእያንዳንዱ መጋዘን ውስጥ የመደርደሪያ / የመደርደሪያ ክፍል ቦታዎችን ይግለጹ (ለምሳሌ መተላለፊያ 2 – መደርደሪያ B)። ዕቃዎች በአካል የት እንደተቀመጡ ለማሳየት ለምርቶች ይመድቧቸው።',
