'Select_Salesperson' => 'ሻጭ ይምረጡ',
'You' => 'እርስዎ',
'Enable_Pos_Salesperson_Switch' => 'በክፍያ ጊዜ ሻጭ ቀይር',
'Enable_Pos_Salesperson_Switch_Hint' => 'ሽያጭ ሳይወጡ ለሌላ ሰራተኛ እንዲመዘገብ በPOS ገጽ ላይ የሻጭ መምረጫ አሳይ። የተመረጠው ሻጭ በደረሰኙ ላይ ይቀመጣል እና በሽያጭ ሪፖርቶች ውስጥ ጥቅም ላይ ይውላል፤ ንቁው የPOS ክፍለ-ጊዜ እንዳለ ይቆያል።',

'Wallet_Payment_Method_Missing' => 'የWallet የክፍያ ዘዴ የለም',
'Wallet_Payment_Method_Missing_Help' => 'በትክክል "Wallet" የሚል ስም ያለው የክፍያ ዘዴ አልተገኘም። የPOS ዋሌት ክፍያ በዚህ ስም ይዛመዳል፤ ስለዚህ "Wallet" የሚል ስም ያለው የክፍያ ዘዴ እዚህ እስኪጨምሩ ድረስ ደንበኞች በዋሌታቸው መክፈል አይችሉም፦',

'Show_Previous_Dues_Line' => 'የቀደሙ ያልተከፈሉ ቀሪዎችን መስመር አሳይ',
'Show_Previous_Dues_Line_Desc' => 'ደንበኛው ከዚህ ሽያጭ በፊት የነበረበት ዕዳ። የሚታተመው ከዜሮ በላይ ሲሆን ብቻ ነው።',
'Show_Net_Balance_Line' => 'የተጣራ ቀሪ ሂሳብ መስመር አሳይ',
'Show_Net_Balance_Line_Desc' => 'የቀደሙ ያልተከፈሉ ቀሪዎች እና በዚህ ሽያጭ ላይ አሁንም ያልተከፈለው ድምር። የሚታተመው የቀደሙ ያልተከፈሉ ቀሪዎች ከዜሮ በላይ ሲሆኑ ብቻ ነው።',

'QZ_Tray_Printer' => 'QZ Tray (በዚህ ኮምፒውተር ላይ ያለ ፕሪንተር)',
'QZ_Printer_Name_Hint' => 'QZ Tray በሚሰራበት ኮምፒውተር ላይ የሚታየው የፕሪንተር ስም። የዚያን ኮምፒውተር ነባሪ ፕሪንተር ለመጠቀም ባዶ ይተዉት። ፕሪንተሮችን ለማግኘት ⟳ ን ይጫኑ።',
'QZ_Not_Running' => 'QZ Tray በዚህ ኮምፒውተር ላይ እየሰራ አይደለም። ከqz.io ጭነው እየሰራ ይተዉት፣ ከዚያም QZ ሲጠይቅ ይህን ድረ-ገጽ ይፍቀዱ።',
'Detect_Printers' => 'ፕሪንተሮችን ፈልግ',
'QZ_Download_Cert' => 'ሰርተፊኬት አውርድ (override.crt)',
'QZ_Setup_Title' => 'የQZ Tray ህትመትን እንዴት ማዋቀር እንደሚቻል (አንድ ጊዜ፣ ሌብል በሚያትም እያንዳንዱ ኮምፒውተር ላይ)',
'QZ_Step_Install' => '1. QZ Tray ን በዚህ ኮምፒውተር ላይ ይጫኑ — ከqz.io በነጻ ያውርዱት፣ ከዚያም ያስጀምሩት እና እየሰራ ይተዉት (በWindows ላይ በሲስተም ትሬይ፣ በmacOS ላይ በሜኑ ባር ውስጥ ይቀመጣል)።',
'QZ_Step_Connect' => '2. የሌብል ፕሪንተርዎን በUSB ያገናኙ እና በኦፕሬቲንግ ሲስተሙ ውስጥ መጫኑን ያረጋግጡ (Windows፦ Settings > Printers & scanners — macOS፦ System Settings > Printers & Scanners)።',
'QZ_Step_Detect' => '3. በዚህ ኮምፒውተር ላይ ያሉትን ፕሪንተሮች ለማግኘት ከላይ ካለው «የፕሪንተር ስም» አጠገብ ያለውን ⟳ ቁልፍ ይጫኑ፣ ከዚያም የሌብል ፕሪንተርዎን ይምረጡ። የኮምፒውተሩን ነባሪ ፕሪንተር ለመጠቀም መስኩን ባዶ ይተዉት።',
'QZ_Step_Cert' => '4. ያለ ፈቃድ መጠየቂያ መስኮት ለማተም፣ ከታች ያለውን ሰርተፊኬት ያውርዱ እና ስሙን ወደ override.crt ቀይረው ወደ QZ Tray የመጫኛ ፎልደር ይቅዱት (Windows፦ C:\\Program Files\\QZ Tray — macOS፦ /Applications/QZ Tray.app/Contents/Resources — Linux፦ /opt/qz-tray)። ከዚያም QZ Tray ን ዘግተው እንደገና ያስጀምሩት።',
'QZ_Step_Test' => '5. ከታች ያለውን «የሙከራ ሌብል አትም» ይጫኑ። QZ Tray ፈቃድ ከጠየቀ Allow ን ይጫኑ — ሰርተፊኬቱ ከተጫነ እንደገና አይጠይቅም።',
'QZ_Step_Save' => '6. እነዚህን ቅንብሮች ለማስቀመጥ አስገባ የሚለውን ይጫኑ። ከባርኮድ ማተሚያ ገጹ የሚወጡ ሌብሎች ከአሁን ጀምሮ ያለ አሳሽ የህትመት መስኮት በቀጥታ በዚህ ፕሪንተር ላይ ይታተማሉ።',
'QZ_Setup_Note' => 'QZ Tray የሚሰራው እየተጠቀሙበት ባለው ኮምፒውተር ላይ ስለሆነ፣ Stocky በርቀት ሰርቨር ላይ ቢስተናገድም ይህ ይሰራል። ሌብል የሚያትም እያንዳንዱ ኮምፒውተር QZ Tray መጫን አለበት።',

