'Shipping_Zone_Delete_Warning' => 'ዞኑ ይወገዳል እና ደንቦቹ ይሰናከላሉ። ነባር ትዕዛዞች የመላኪያ ዝርዝሮቻቸውን ይይዛሉ።',
