'Enable_Wholesale_Pricing' => 'በብዛት ላይ የተመሰረተ የጅምላ ዋጋ',
'Enable_Wholesale_Pricing_Hint' => 'የታዘዘው ብዛት አንድ ደረጃ ላይ ሲደርስ በPOS እና በኦንላይን ሱቁ ውስጥ የችርቻሮ ዋጋውን በራስ-ሰር የሚተኩ የብዛት ደረጃዎች (10-19 ፍሬ፣ 20-49 ፍሬ፣ 100+ ...) ምርቶች እንዲኖራቸው ይፍቀዱ። ካጠፉት ሁሉም ነገር እንደገና በመደበኛ የችርቻሮ ዋጋ ይሸጣል — የተዋቀሩ ደረጃዎች ይቀመጣሉ፣ ግን አይተገበሩም።',
'Wholesale_Pricing_By_Quantity' => 'በብዛት ላይ የተመሰረተ የጅምላ ዋጋ',
'Wholesale_Pricing_By_Quantity_Hint' => 'የታዘዘው ብዛት አንድ ደረጃ ላይ ሲደርስ የአንድ ፍሬ ዋጋ። ለመጨረሻው ገደብ የሌለው ደረጃ (ለምሳሌ 100 እና ከዚያ በላይ) ከፍተኛውን ባዶ ይተዉት። ከመጀመሪያው ደረጃ በታች ምርቱ በመደበኛ የችርቻሮ ዋጋው ይሸጣል።',
'Wholesale_Pricing_Variants_Hint' => 'አንድ የደረጃ ሰንጠረዥ ሙሉውን ምርት ይሸፍናል፦ እያንዳንዱ ዓይነት የራሱ መስመር አንድ ደረጃ ላይ ሲደርስ በደረጃው ዋጋ ይሸጣል።',
