/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'የትዕዛዞች መመሪያ',
'Ord_Guide_Intro' => 'በኦንላይን ሱቅዎ ላይ የተሰጠ ትዕዛዝ ወደ ክምችትዎ እና ወደ ሂሳቦችዎ እንዴት እንደሚጓዝ፣ እና ገንዘቡ በእርግጥ የት እንደሚመዘገብ።',
'Ord_Guide_Lifecycle_Title' => 'የትዕዛዝ ሁኔታ',
'Ord_Guide_Lifecycle_Pending' => 'ግምገማዎን የሚጠብቅ አዲስ ትዕዛዝ። ሊረጋገጥ ወይም ሊሰረዝ የሚችለው በመጠባበቅ ላይ ያለ ትዕዛዝ ብቻ ነው።',
'Ord_Guide_Lifecycle_Confirmed' => 'ትዕዛዙን ተቀብለዋል። Stocky በመረጡት መጋዘን ውስጥ ሽያጭ ይፈጥራል እና ክምችቱን ይቀንሳል — ያ ሽያጭ የክምችት፣ የክፍያ እና የትርፍ ሪፖርቶችዎ የሚያነቡት መዝገብ ነው።',
'Ord_Guide_Lifecycle_Shipped' => 'ትዕዛዙን ልከዋል። ይህ ማስፈጸም ብቻ ነው፦ ሲያረጋግጡ ክምችቱ አስቀድሞ ተቀንሷል።',
'Ord_Guide_Lifecycle_Delivered' => 'ደንበኛው ትዕዛዙን ተቀብሏል። የመመለሻ ጊዜውን የሚያስጀምረው ይህ ነው።',
'Ord_Guide_Lifecycle_Cancelled' => 'ትዕዛዙ ከመረጋገጡ በፊት ተሰርዟል፤ ስለዚህ ምንም ሽያጭ አልተፈጠረም፣ ምንም ክምችትም አልተቀነሰም።',
'Ord_Guide_PaymentStatus_Tip' => 'በክፍያ ጊዜ የተዘጋጀ ሲሆን እዚህ ሊስተካከል አይችልም። ክፍያውን እንዴት እንደሚመዘግቡ ለማየት ይጫኑ።',
'Ord_Guide_Payment_Title' => 'የክፍያ ሁኔታ',
'Ord_Guide_Payment_Intro' => 'ይህ አምድ ደንበኛው በክፍያ ጊዜ እንዴት ለመክፈል እንደመረጠ ይመዘግባል። በሱቁ የሚዘጋጅ ሲሆን ከዚህ ገጽ ሊስተካከል አይችልም — ገንዘቡ ራሱ የሚከታተለው ትዕዛዙን ማረጋገጥ በሚፈጥረው ሽያጭ ላይ ነው።',
'Ord_Guide_Payment_Paid' => 'ደንበኛው አስቀድሞ በክፍያ መግቢያ (payment gateway) በኦንላይን ከፍሏል። ትዕዛዙን ማረጋገጥ ሽያጩን እንደ ተከፍሏል ይፈጥራል እና ክፍያውን ለእርስዎ ይመዘግባል — ሌላ ማድረግ ያለብዎት ነገር የለም።',
'Ord_Guide_Payment_Pending' => 'በማድረስ ጊዜ በጥሬ ገንዘብ፣ በባንክ ዝውውር ወይም በሌላ በኋላ የሚከፈል ዘዴ። ትዕዛዙን ማረጋገጥ ሽያጩን እንደ አልተከፈለም ይፈጥራል፤ ስለዚህ ገንዘቡን ሲሰበስቡ እራስዎ ይመዘግቡታል — ከታች ያሉትን ደረጃዎች ይመልከቱ።',
'Ord_Guide_Payment_Failed' => 'የክፍያ መግቢያው ክፍያውን ውድቅ አድርጓል ወይም ደንበኛው ትቶታል። ትዕዛዙ በራስ-ሰር ይሰረዛል።',
'Ord_Guide_MarkPaid_Title' => 'ክፍያን ከመጠባበቅ ወደ ተከፍሏል መቀየር',
'Ord_Guide_MarkPaid_Step1' => 'መጀመሪያ ትዕዛዙን እዚህ ያረጋግጡ — ሽያጩን የሚፈጥረው ማረጋገጥ ነው።',
'Ord_Guide_MarkPaid_Step2' => 'ሽያጮች > ሁሉም ሽያጮች ን ይክፈቱ እና ያንን ሽያጭ ያግኙ (ተመሳሳይ ደንበኛ፣ እና የዝርዝሮች ገጹ የመጣበትን የኦንላይን ትዕዛዝ ያሳያል)።',
'Ord_Guide_MarkPaid_Step3' => 'የረድፍ እርምጃዎች ሜኑውን ይክፈቱ እና ክፍያ ፍጠር የሚለውን ይምረጡ።',
'Ord_Guide_MarkPaid_Step4' => 'መጠኑን፣ የክፍያ ዘዴውን እና ቀኑን ያስገቡ፣ ከዚያም ያስቀምጡ። ሽያጩ እንደ መጠኑ በራሱ ወደ ከፊል ወይም ተከፍሏል ይሸጋገራል።',
'Ord_Guide_MarkPaid_Note' => 'እዚህ የሚታየው የክፍያ ሁኔታ የክፍያ ጊዜውን ምርጫ መመዝገቡን ይቀጥላል እና እንዳለ ይቆያል። ሽያጩ የሂሳብ መዝገቡ ሲሆን የክፍያ እና የትርፍ ሪፖርቶችዎን የሚመግበው እሱ ነው። ያስገቡትን ለመገምገም ወይም ለማስተካከል በሽያጩ ላይ ክፍያዎችን አሳይ የሚለውን ይጠቀሙ።',
'Ord_Guide_Notes_Title' => 'ማወቅ ጠቃሚ ነው',
'Ord_Guide_Note_Warehouse' => 'ሲያረጋግጡ የሚመርጡት መጋዘን ክምችቱ ከየት እንደሚወሰድ ይወስናል። ሙሉውን ትዕዛዝ መሸፈን የማይችሉ መጋዘኖች በዚያ ዝርዝር ውስጥ ክምችት አልቋል ተብለው ምልክት ይደረግባቸዋል።',
'Ord_Guide_Note_Preorder' => 'የቅድመ-ትዕዛዝ ዕቃዎች የክምችት ፍተሻን ያልፋሉ፤ ስለዚህ እነሱን የያዘ ትዕዛዝ ብዛቱ ገና በእጅ ባይኖርም ሊረጋገጥ ይችላል።',
'Ord_Guide_Note_Flagged' => 'የተጠቆመ የሚል መለያ ትዕዛዙ በክፍያ ጊዜ የማጭበርበር ፍተሻ አስነስቷል ማለት ነው። ምክንያቱን ለማየት ጠቋሚውን በመለያው ላይ ያድርጉ እና ከማረጋገጥዎ በፊት ትዕዛዙን ይገምግሙ።',
'Ord_Guide_Note_Cancel' => 'መሰረዝ የሚቻለው ትዕዛዙ ገና በመጠባበቅ ላይ እያለ ብቻ ነው። አንዴ ከተረጋገጠ በምትኩ በሽያጩ ወይም በደንበኛ መመለሻ በኩል ይቀልብሱት።',


