'VG_Opt_Step3' => 'እሴት ይጻፉ (ለምሳሌ ቀይ) እና Enter ይጫኑ። ለእያንዳንዱ እሴት ይድገሙ፤ ኮማም እሴቶችን ይለያል። እሴትን ለማስወገድ በላዩ ላይ ያለውን x ጠቅ ያድርጉ።',
'VG_Opt_Step4' => 'ለሁለተኛ ወይም ለሦስተኛ አማራጭ "አማራጭ ጨምር"ን ጠቅ ያድርጉ (ቢበዛ 3 አማራጮች)።',
'VG_Opt_Step5' => '"ዓይነቶችን ፍጠር"ን ጠቅ ያድርጉ። ለእያንዳንዱ ጥምረት አንድ ረድፍ ይፈጠራል፤ ስሙም በራስ-ሰር ይገነባል፣ ለምሳሌ "Red / S"።',
'VG_Opt_Step6' => 'በእያንዳንዱ ረድፍ ወጪ እና ዋጋ ያስገቡ፣ ወይም በ"ለሁሉም ተግብር" ውስጥ እሴት ጽፈው ወደ ሁሉም ረድፎች ለመቅዳት ወጪ ወይም ዋጋን ጠቅ ያድርጉ።',
'VG_Opt_Step7' => 'ኮዶች በራስ-ሰር ይፈጠሩልዎታል። የራስዎን ይጻፉ ወይም ሌላ ለመፍጠር የማደሻ አዶውን ጠቅ ያድርጉ።',
'VG_Opt_Step8' => 'አማራጭ፦ በአንድ አማራጭ ላይ "የቀለም ናሙናዎች"ን ምልክት ያድርጉ እና ለእያንዳንዱ እሴት ቀለም ይምረጡ፤ ሱቁ እንደ ባለቀለም ነጥብ ያሳየዋል።',
'VG_Rows_Title' => 'የዓይነት ረድፎች',
'VG_Rows_Text' => 'እያንዳንዱ ረድፍ ምስል፣ ኮድ፣ ባርኮድ፣ ወጪ፣ ዋጋ፣ የጅምላ ዋጋ እና ዝቅተኛ የመሸጫ ዋጋ አለው። ምርት ሲፈጥሩ ለእያንዳንዱ ዓይነት በየመጋዘኑ የመነሻ ክምችትም ማስገባት ይችላሉ። "ያልተሟላ" የሚል መለያ ረድፉ ለአንድ አማራጭ እሴት እንደጎደለው ያሳያል።',
'VG_List_Title' => 'የቀላል ዝርዝር ሁነታ',
'VG_List_Text' => 'ረድፍ ለመጨመር የዓይነት ስም ይጻፉ እና Enter ይጫኑ (ወይም ጨምርን ጠቅ ያድርጉ)፣ ከዚያ ኮዱን እና ዋጋዎቹን ይሙሉ። ይህ የተለመደው አሰራር ሲሆን ለነባር ምርቶች መገኘቱን ይቀጥላል።',
'VG_Edit_Title' => 'በኋላ ማስተካከል',
'VG_Edit_1' => 'እሴት ጨምረው "ዓይነቶችን ፍጠር"ን ጠቅ ያድርጉ፦ የጎደሉት ጥምረቶች ብቻ ይታከላሉ። ነባር ረድፎች ኮዶቻቸውን፣ ዋጋዎቻቸውን እና ታሪካቸውን ይይዛሉ።',
'VG_Edit_2' => 'እሴትን ወይም አማራጭን ማስወገድ የሚጠቀሙትን ረድፎች ያስወግዳል። አስቀድመው የተቀመጡ ረድፎች ከማረጋገጫ በኋላ ምርቱን ሲያስቀምጡ ይሰረዛሉ።',
'VG_Edit_3' => 'አሁንም ክምችት ያለው ዓይነት ሊወገድ አይችልም። መጀመሪያ ክምችቱን ያስተካክሉ ወይም ያዛውሩ።',
'VG_Edit_4' => 'ወደ "ቀላል ዝርዝር" መቀየር ረድፎቹን እና ስሞቻቸውን ያቆያል፣ ነገር ግን የአማራጭ ፍቺዎቹን ያስወግዳል።',
'VG_Store_Title' => 'በኦንላይን ሱቁ ላይ',
'VG_Store_Text' => 'ደንበኞች ለእያንዳንዱ አማራጭ አንድ እሴት ይመርጣሉ፣ ለምሳሌ መጀመሪያ ቀለም ከዚያ መጠን። የሌሉ ጥምረቶች ይሰናከላሉ፣ ክምችት ያለቀባቸውም ይሰረዛሉ (በመስመር ይቆረጣሉ)። ወደ ጋሪው የሚገባው የተመረጠው ዓይነት ነው።',
'Choose_Source' => 'ምንጭ ይምረጡ',
'Portal_Request' => 'የፖርታል ጥያቄ',
'Portal_Quotation_Requests' => 'የፖርታል የዋጋ ማቅረቢያ ጥያቄዎች',
'Warehouse_Invoice_Address_Help' => 'በዚህ መጋዘን በሚሰጡ ደረሰኞች ላይ የሚታተም የመንገድ አድራሻ። ከቅንብሮቹ የኩባንያውን አድራሻ ለመጠቀም ባዶ ይተዉት።',
'Warehouse_Logo_Help' => 'በዚህ መጋዘን ደረሰኞች እና POS ደረሰኞች ላይ የሚታተም አርማ። የኩባንያውን አርማ ለመጠቀም ባዶ ይተዉት።',
'Warehouse_Invoice_Footer_Help' => 'በዚህ መጋዘን በሚሰጡ ደረሰኞች ግርጌ ላይ የሚታተም ተጨማሪ ማስታወሻ።',
'Issued_By' => 'የሰጠው',
'Enable_Warehouse_Letterhead' => 'በደረሰኞች ላይ የመጋዘን ደብዳቤ ራስጌ',
'Enable_Warehouse_Letterhead_Hint' => 'ደረሰኙን የሰጠውን መጋዘን በደረሰኞች፣ በPOS ደረሰኞች እና በይፋዊው የደረሰኝ ገጽ ላይ ያትሙ፦ ስሙ የኩባንያውን ስም ይተካል፣ አድራሻው፣ ስልኩ፣ ኢሜይሉ፣ አርማው እና የግርጌ ማስታወሻው የኩባንያውን ይተካሉ። በመጋዘኑ ላይ ባዶ የተተወ ማንኛውም መስክ ወደ አጠቃላይ የኩባንያ ቅንብሮች ይመለሳል።',
'Warehouse_Letterhead_Receipt_Notice' => 'የመጋዘን ደብዳቤ ራስጌ በርቷል፦ በእውነተኛ ደረሰኝ ላይ የሚታተሙት የሱቁ ስም፣ አድራሻ እና ስልክ ሽያጩን ከሰጠው መጋዘን ይመጣሉ፣ የግርጌ ማስታወሻውም ከደንበኛው ማስታወሻ በታች ይታከላል።',
'Warehouse_Letterhead_Receipt_Demo' => 'የቅርንጫፍ ግርጌ ማስታወሻ — በመጋዘኖች ስር ለእያንዳንዱ መጋዘን ይዘጋጃል።',
