'Set_Demo_Intro_Desc' => 'ባለፉት 90 ቀናት ውስጥ የተሰራጩ ምርቶች፣ ደንበኞች፣ አቅራቢዎች፣ ሽያጮች፣ ግዢዎች፣ የዋጋ ማቅረቢያዎች እና ወጪዎች — ዳሽቦርዶችን እና ሪፖርቶችን ለመዳሰስ ተስማሚ። የተፈጠረው ሁሉ ምልክት ተደርጎበታል፣ በአንድ ጠቅታም ሊወገድ ይችላል።',
