'Upd_Guide_Running_Title' => '2. ዝማኔውን ማስኬድ',
'Upd_Guide_Run_Open' => '{path}ን (ይህን ገጽ) ይክፈቱ እና በ{tab} ትር ላይ ይቆዩ።',
'Upd_Guide_Run_Upload' => '{upload}፦ የወረደውን ጥቅል ጠቅ አድርገው ወይም ጎትተው ወደ መስቀያ ሳጥኑ ያስገቡ። ትላልቅ ፋይሎች በትናንሽ ቁርጥራጮች ይሰቀላሉ፣ ስለዚህ ይህ ዝቅተኛ የመስቀያ ገደብ ባላቸው የጋራ ሆስቲንግ ላይም ይሰራል። ቼክሰም ከተበላሹ ወይም ካልተሟሉ ስቀላዎች ይጠብቃል።',
'Upd_Upload_The_Zip' => 'ZIPውን ይስቀሉ',
'Upd_Guide_Run_Validation' => 'ከስቀላው በኋላ {auto} ({button} አዝራሩን በመጠቀም እንደገና ማስኬድ ይችላሉ)። ሲስተሙ የሚፈትሻቸው፦ የZIP ታማኝነት፣ የጥቅል መዋቅር እና ሙሉነት፣ የስሪት ተኳሃኝነት (ወደ ቀድሞ ስሪት መመለስ ውድቅ ይደረጋል)፣ የሚያስፈልገው የPHP ስሪት እና ቅጥያዎች፣ የፋይል ፈቃዶች፣ ነጻ የዲስክ ቦታ፣ የዳታቤዝ ግንኙነት፣ ውቅር፣ እና ሌላ ዝማኔ እየሄደ አለመሆኑን ነው።',
'Upd_Validation_Runs_Automatically' => 'ማረጋገጫ በራስ-ሰር ይካሄዳል',
