'Upd_Guide_Phase_Verify' => '{label} — የጤና ፍተሻዎች አዲሱ ስሪት መነሳቱን፣ ዳታቤዙ መስራቱን፣ ሁሉም ማይግሬሽኖች መሰራታቸውን እና ውቅሩ ትክክል መሆኑን ያረጋግጣሉ።',
