'Upd_Guide_Wrong_Interrupted' => '{label} (የሰርቨር ዳግም መነሳት፣ የጊዜ ገደብ ማለፍ፣ የተዘጋ አሳሽ፣ የኃይል መቋረጥ) — ይህን ገጽ እንደገና ሲከፍቱ ቀይ ባነር ሁለት ደህንነታቸው የተጠበቀ ምርጫዎችን ያቀርባል፦ {resume} (ከቆመበት ትክክለኛ ደረጃ ይቀጥላል) ወይም {rollback} (የቀድሞውን ስሪት ከመጠባበቂያው ይመልሳል)።',
