'Upd_Another_Admin_Updating' => 'ሌላ አስተዳዳሪ በተመሳሳይ ጊዜ ለማዘመን ቢሞክር',
'Upd_Guide_Backups_Title' => '4. መጠባበቂያዎች እና መመለስ',
'Upd_Guide_Backups_Created' => 'እያንዳንዱ ዝማኔ ምንም ነገር ከመንካቱ {before} መጠባበቂያ ይፈጥራል፦ ዝማኔው ሊተካቸው የሚችላቸው ሁሉም የመተግበሪያ ፋይሎች፣ የ{env} ቅጂ እና ሙሉ የዳታቤዝ ቅጂ። የተሰቀሉ ፋይሎች እና {storage} በዝማኔ በፍጹም ስለማይቀየሩ የመጠባበቂያው አካል አይደሉም — የእነሱን የራስዎን መጠባበቂያ ያስቀምጡ። መጠባበቂያዎች በ{path} ውስጥ ይቀመጣሉ፣ ከድርም በፍጹም ሊደረስባቸው አይችሉም።',
'Upd_Before' => 'በፊት',
'Upd_Guide_Backups_Panel' => 'በ{tab} ትር ላይ ያለው የ{panel} ፓነል ከቀን፣ ስሪት እና መጠን ጋር ይዘረዝራቸዋል። ከዚያ ማንኛውንም ሙሉ መጠባበቂያ {restore} (ፋይሎች + ዳታቤዝ — መጀመሪያ የአሁኑ ዳታቤዝ የደህንነት ቅጂ ይወሰዳል) ወይም የቆዩትን {delete} ይችላሉ።',
'Upd_Restore_Verb' => 'መመለስ',
'Upd_Delete_Verb' => 'መሰረዝ',
'Upd_Guide_Backups_Retention' => 'ስንት መጠባበቂያዎች እንደሚቆዩ ለመምረጥ {keep}ን ይጠቀሙ፤ የቆዩት ከእያንዳንዱ የተሳካ ዝማኔ በኋላ በራስ-ሰር ይወገዳሉ። ብቸኛው ቀሪ ሙሉ መጠባበቂያ በፍጹም ሊሰረዝ አይችልም — ሁልጊዜ የመመለሻ መንገድ ይኖርዎታል።',
'Upd_Guide_Manual_Title' => '5. በእጅ ማዘመን (አማራጭ ዘዴ)',
'Upd_Guide_Manual_Text' => 'በእጅ ማዘመንን ከመረጡ ወይም መስቀያው በሰርቨርዎ ላይ መጠቀም ካልተቻለ በዚህ ገጽ {tab} ትር ላይ ያሉትን የደረጃ በደረጃ መመሪያዎች ይከተሉ።',
'Upd_Guide_Clear_Cache_First' => 'ከማንኛውም ዝማኔ በኋላ ገጾች የተበላሹ ወይም ባዶ ከመሰሉ መጀመሪያ የአሳሽዎን ካሽ ያጽዱ — ምክንያቱ ሁልጊዜ ማለት ይቻላል እሱ ነው።',
'Upd_Restore_Backup_Confirm' => 'ይህ መጠባበቂያ ይመለስ? የአሁኑ ፋይሎች እና የአሁኑ ዳታቤዝ በመጠባበቂያው ይተካሉ። መጀመሪያ የአሁኑ ዳታቤዝ የደህንነት ቅጂ ይወሰዳል። (v{version} — {date})',
'Woo_Guide_Lead' => 'የWooCommerce ሱቅ ከERP ጋር እንዴት ተጣጥሞ እንደሚቆይ። ከታች ያሉት የcron መስመሮች ለዚህ ሰርቨር የተዘጋጁ ናቸው፣ ስለዚህ በቀጥታ ተቀድተው ሊገቡበት ይችላሉ።',
'Woo_Guide_Ways_Note' => 'ከShopify በተለየ WooCommerce በራሱ ወደ ERP ምንም አይልክም — እዚህ የWebhook መቀበያ የለም፣ ስለዚህ {in} የሚመጣው ሁሉ በመርሃ ግብሩ ይደርሳል። ወዲያውኑ ሊሆን የሚችለው {out} የሚሄደው ክምችት ብቻ ነው።',
'Woo_In' => 'ወደ ውስጥ',
'Woo_Out' => 'ወደ ውጭ',
'Woo_Guide_Both_Ways_Title' => 'ሁለቱም መንገዶች መጀመሪያ ይህን ይፈልጋሉ',
'Woo_Api_Keys' => 'የAPI ቁልፎች',
'Woo_Guide_Api_Keys_Text' => '{path}፣ ፈቃድ {perm}። የconsumer key እና secretን ከሱቁ URL ጋር ወደ {settings} ትር ይቅዱ — የጣቢያዎ አድራሻ ያለ መጨረሻ ስላሽ፣ ለምሳሌ {example}።',
'Woo_Credentials_Saved' => 'የመግቢያ መረጃዎች ተቀምጠዋል',
'Woo_Not_Configured_Yet' => 'ገና አልተዋቀረም',
'Woo_Guide_Wp_App_Password_Title' => 'የWordPress መተግበሪያ የይለፍ ቃል (አማራጭ)',
'Woo_Guide_Wp_App_Password_Text' => 'ለምርት ምስሎች ብቻ ጥቅም ላይ ይውላል። የWooCommerce API ምርቶችን፣ ክምችትን፣ ምድቦችን፣ ብራንዶችን፣ ደንበኞችን እና ትዕዛዞችን ያንቀሳቅሳል፤ የMedia Libraryን የሚፈልገው እና እዚያ ገና የሌለ ምስልን የሚሰቅለው የWordPress API ነው።',
'Woo_Guide_Wp_App_Password_Note' => 'ሚዲያን ማስተዳደር የሚችል የWordPress ተጠቃሚ ይጠቀሙ፣ የይለፍ ቃሉንም በ{path} ስር ይፍጠሩ። ሁለቱንም መስኮች ባዶ ቢተዉም ሁሉም ነገር ይመሳሰላል — የሚዘለለው ምስል ማያያዝ ብቻ ነው።',
'Woo_Guide_Pick_Way_Title' => 'ከዚያ እንዴት ተጣጥሞ እንደሚቆይ ይምረጡ',
'Woo_Right_Away' => 'ወዲያውኑ',
'Woo_Stock_Live' => 'ክምችት ቀጥታ',
'Woo_Stock_Not_Live' => 'ክምችት ቀጥታ አይደለም',
'Woo_Guide_Realtime_Lead' => 'አንድ አቅጣጫ ብቻ፦ ከERP የሚወጡ ክምችት እና ምርቶች። በWooCommerce ውስጥ የተደረጉ ትዕዛዞች እና የምርት ማስተካከያዎች አሁንም በመርሃ ግብሩ ይደርሳሉ — ሌላኛውን ትር ይመልከቱ።',
'Woo_Push_Stock_On_Change' => 'ክምችት በተቀየረበት ቅጽበት ላክ',
'Woo_Setting_People_Miss' => 'ሰዎች የሚዘነጉት ቅንብር ይህ ነው',
'Woo_Guide_Pos_Sale_Not_Reach' => 'የPOS ሽያጭ በራሱ WooCommerce ላይ {not}። ጠፍቶ ከተተወ ሱቁ የሚያውቀው በሚቀጥለው የክምችት ማመሳሰል ላይ ብቻ ነው — በነባሪ ከአንድ ሰዓት በኋላ — በዚያ ጊዜ ውስጥም በካሽ ሬጂስተሩ ላይ አስቀድመው የሸጡትን ዕቃ ሊሸጥ ይችላል።',
'Woo_Does_Not' => 'አይደርስም',
'Woo_Guide_Tick_Instant' => 'በ{settings} ትር ላይ {option}ን ምልክት ያድርጉ። ሙሉ ዝግጅቱ ያ ብቻ ነው — ወርከር የለም፣ cron የለም። ከዚያ እያንዳንዱ ሽያጭ፣ መመለሻ፣ ማስተካከያ፣ ዝውውር እና የተቀበለ ግዢ ሽያጩ እንደተቀመጠ ወዲያውኑ የእነዚያን ምርቶች ብቻ መላኪያ ይልካል፣ ሃያ መስመር ያለው ሽያጭም ሃያ ሳይሆን አንድ መላኪያ ብቻ ይጠይቃል። ካሽ ሬጂስተሩ በፍጹም አይጠብቀውም።',
'Woo_Currently' => 'በአሁኑ ጊዜ፦',
'Woo_Instant_On_Text' => 'በርቷል — ክምችት ሲቀየር ይላካል',
'Woo_Instant_Off_Text' => 'ጠፍቷል — ክምችት በመርሃ ግብሩ ብቻ',
'Woo_Guide_Instant_Note' => 'የሚላኩት አስቀድመው ከWooCommerce ጋር የተገናኙ ምርቶች ብቻ ናቸው — በፍጹም ያልተመሳሰለ ምርት በሱቁ ውስጥ የሚስተካከል ነገር የለውም። ተለዋዋጭ ምርቶች በወላጃቸው በኩል ይሄዳሉ፣ ኮምቦ ደግሞ ማንኛውም ክፍሉ ሲንቀሳቀስ እንደገና ይላካል። የጅምላ ስራዎች (ምርትን መሰረዝ፣ መጋዘንን ዳግም ማስጀመር) ክስተት ሳያስነሱ ክምችትን ይጽፋሉ፣ ይህም የሰዓቱን የክምችት ማመሳሰል እንዲቆይ ከሚያደርጉ ምክንያቶች አንዱ ነው።',
'Woo_Push_Products_On_Save' => 'ምርቶች በተቀመጡበት ቅጽበት ላክ',
'Woo_Guide_Tick_Auto_Products' => 'በ{settings} ትር ላይ {option}ን ምልክት ያድርጉ፣ በStocky ውስጥ የተፈጠረ፣ የተስተካከለ ወይም የተባዛ ምርት እንደተቀመጠ ወዲያውኑ ወደ WooCommerce ይላካል — ዝርዝሮች፣ ዋጋ፣ ዓይነቶች እና ምስሎች፣ ከዚያም ክምችቱ። አዲስ ምርት የምሽቱን የምርቶች ማመሳሰል ሳይጠብቅ ወዲያውኑ በሱቁ ውስጥ ይፈጠራል።',
'Woo_On' => 'በርቷል',
'Woo_Off' => 'ጠፍቷል',
'Woo_Guide_Bulk_Imports_Note' => 'የጅምላ ማስገቢያዎች አንድ በአንድ አይላኩም — ከማስገባት በኋላ የምርቶች ማመሳሰል ያሂዱ። የተላከ ምርት በትክክለኛው ምድብ ውስጥ እንዲገባ መጀመሪያ ምድቦችን እና ብራንዶችን ያመሳስሉ።',
'Woo_Nothing_Else_To_Install' => 'ሌላ የሚጫን ነገር የለም',
'Woo_Guide_Same_Process' => 'የወረፋ ወርከር የለም፣ የcron ግቤት የለም። መላኪያው ሽያጩን ባገለገለው ተመሳሳይ ሂደት ውስጥ ምላሹ ከተመለሰ {after} ይሄዳል፣ ስለዚህ ካሽ ሬጂስተሩ WooCommerceን በፍጹም አይጠብቅም። መላኪያዎች በፍጹም አይደራረቡም፦ አንዱ እየሄደ ሳለ የተደረጉ ለውጦች ይጠብቁታል፣ ወዲያውኑ ከእሱ በኋላም ይላካሉ።',
'Woo_After' => 'በኋላ',
'Woo_Guide_Shop_Stops_Answering' => 'ምላሽ መስጠት ያቆመ ሱቅ ከስምንት ሰከንድ በኋላ ይተዋል፣ እያንዳንዱ ሽያጭ እንደገና እንዳይጠብቀው መላኪያዎች ለአምስት ደቂቃዎች ይቆማሉ፤ በዚያ ጊዜ የመጡ ለውጦች ከቆይታው በኋላ ባለው የመጀመሪያ መላኪያ ይሄዳሉ፣ የሰዓቱ የክምችት ማመሳሰልም ምንም ቢሆን ያሟላል። እያንዳንዱ ቆይታ በምዝግብ ማስታወሻዎች ትር ውስጥ ይመዘገባል።',
'Woo_Guide_Artisan_Exception' => 'አንድ ልዩ ሁኔታ፦ በartisan ትዕዛዝ የተደረገ የክምችት ለውጥ የሚከተለው ምላሽ ስለሌለው በምትኩ በ{queue} ወረፋ ላይ ይቀመጣል። እነዚያም በፍጥነት እንዲላኩ ያንን ወረፋ ያስኪዱ፦',
'Woo_Cron_Line_Copied' => 'የcron መስመር ተቀድቷል',
'Woo_Command_Copied' => 'ትዕዛዙ ተቀድቷል',
'Woo_Guide_Not_Woo_Queue' => 'ሆን ተብሎ የ{queue} ወረፋ አይደለም፦ ያኛው ለሰዓታት የሚቆዩ የካታሎግ ባቾችን ይይዛል፣ ከአንዱ ጀርባ ወረፋ የያዘ ፈጣን መላኪያም ፈጣን አይሆንም።',
'Woo_On_A_Schedule' => 'በመርሃ ግብር',
'Woo_Guide_Scheduled_Lead' => 'ሁሉም ነገር በየተወሰነ ጊዜ በሁለቱም አቅጣጫዎች እንደገና ይፈተሻል። ትዕዛዞች ወደ ERP የሚደርሱት፣ ካታሎግ የሚታተመው እና ፈጣኑ መንገድ ያመለጠውን ሁሉ የሚጠገነው በዚህ መንገድ ነው። እያንዳንዱ ስራ የራሱ የcron ግቤት አለው፣ ስለዚህ የሚፈልጉትን ብቻ ያስኬዳሉ።',
'Woo_Guide_Sync_Drains_Queue' => '{command} በሚሄድበት ጊዜ የራሱን ወረፋ ያስኬዳል፣ ስለዚህ እነዚህ መስመሮች የተለየ ወርከር አያስፈልጋቸውም። በWindows ላይ Task Schedulerን በፕሮግራም {program} እና በተመሳሳይ ነጋሪ እሴቶች፣ በ{path} ውስጥ የሚጀምር አድርገው ይጠቀሙ።',
'Woo_Or_No_Cron' => 'ወይም ምንም cron የለም',
'Woo_Guide_No_Cron_Text' => 'እዚህ ያለው እያንዳንዱ ትር በፍላጎት ያመሳስላል፣ በእጅ የሚደረግ ማመሳሰልም ገጹ ክፍት ሳለ የራሱን ባቾች ያስኬዳል — ስለዚህ ትንሽ ሱቅ ያለ ምንም የcron ግቤት ሊሰራ ይችላል። የሚያጡት ማንም በማይመለከትበት ጊዜ የሚሆነውን ሁሉ ነው፦ ትዕዛዞች የሚደርሱት አንድ ሰው አዝራሩን ሲጫን ብቻ ነው።',
'Woo_Commands_Worth_Knowing' => 'ማወቅ የሚገባቸው ትዕዛዞች',
'Woo_Worth_Knowing' => 'ማወቅ የሚገባው',
'Woo_Guide_Changing_Url_Clears' => 'የሱቁን URL ወይም የAPI ቁልፎችን መቀየር ሁሉንም ማዛመጃዎች ያጸዳል — ምርቶች፣ ምድቦች፣ ብራንዶች እና ደንበኞች ሁሉም ወደ አዲሱ ሱቅ እንደገና ይመሳሰላሉ።',
