'Woo_Guide_Page_Subtitle' => 'ሱቁን ማገናኘት፣ በራሱ የሚሄደው እና ለዚህ ሰርቨር የcron ግቤቶች',
'Woo_Settings_Button' => 'የWooCommerce ቅንብሮች',
'Woo_No_Shop_Connected' => 'ገና ምንም ሱቅ አልተገናኘም',
'Woo_No_Shop_Connected_Desc' => 'ከታች ያለው ሁሉ አሁንም ይሰራል — በWooCommerce ቅንብሮች ገጽ ላይ የሱቁን URL እና የAPI ቁልፎችን ያስገቡ፣ ከዚያ ይመለሱ።',
'Woo_Wp_Username' => 'የWordPress የተጠቃሚ ስም',
'Woo_Wp_App_Password' => 'የWordPress መተግበሪያ የይለፍ ቃል',
'Woo_Settings_Instant_Hint' => 'ሽያጭ፣ መመለሻ ወይም ማስተካከያ በተቀመጠበት ቅጽበት የእነዚያን ምርቶች ብቻ የክምችት መላኪያ ይልካል፣ ስለዚህ ሱቁ በሚቀጥለው የሰዓት የክምችት ማመሳሰል ሳይሆን በሰከንዶች ውስጥ ትክክል ይሆናል። ሌላ የሚጫን ነገር የለም — መላኪያው የሚሄደው ሽያጩ ምላሽ ካገኘ በኋላ ነው፣ ስለዚህ ካሽ ሬጂስተሩ WooCommerceን በፍጹም አይጠብቅም። ተጨማሪ በ{guide} ትር ላይ።',
'Woo_Settings_Instant_Off_Alert' => 'ጠፍቶ ከተተወ የPOS ሽያጭ WooCommerce ላይ የሚደርሰው በሚቀጥለው የክምችት ማመሳሰል ብቻ ነው — እስከ አንድ ሰዓት ዘግይቶ።',
'Woo_Settings_Auto_Products_Hint' => 'በStocky ውስጥ የተፈጠረ፣ የተስተካከለ ወይም የተባዛ ምርት የምርቶች ማመሳሰልን ሳይጠብቅ እንደተቀመጠ ወዲያውኑ ወደ WooCommerce ይላካል — ዝርዝሮች፣ ዋጋ፣ ዓይነቶች፣ ምስሎች፣ ከዚያም ክምችቱ። የጅምላ ማስገቢያዎች አይላኩም፤ ከማስገባት በኋላ የምርቶች ማመሳሰል ያሂዱ።',
'Woo_Sync_Tuning' => 'የማመሳሰል ማስተካከያ',
'Woo_Sync_Tuning_Intro' => 'ነባሪዎቹ ለአብዛኞቹ ሱቆች ይስማማሉ። እነዚህን የሚቀይሩት ማመሳሰል ቀርፋፋ ከሆነ ወይም በሆስቲንግዎ ላይ የጊዜ ገደቡ ካለፈ ብቻ ነው። እያንዳንዱ እሴት በደህንነቱ የተጠበቀ ክልል ውስጥ የተገደበ ነው፣ መስክን ማጽዳትም ነባሪውን ይመልሳል።',
'Woo_Setting_This_Up' => 'ይህን ማዋቀር',
'Woo_Setting_This_Up_Text' => 'የAPI ቁልፎችን ማግኘት፣ የWordPress መተግበሪያ የይለፍ ቃል ለምን እንደሆነ፣ ለታቀዱ ማመሳሰሎች የcron ግቤቶች፣ እና ክምችት በተቀየረበት ቅጽበት ሱቁ ላይ እንዲደርስ እንዴት ማድረግ እንደሚቻል — ሁሉም፣ የዚህ ሰርቨር የራሱ የcron መስመሮች ለመቅዳት ዝግጁ ሆነው፣ በመመሪያ ትር ላይ ይገኛሉ። አንድ ቅጂ ብቻ ስለሆነ ሞጁሉ በትክክል ከሚሰራው ሊለይ አይችልም።',
