'Telegram_G_A_Body' => 'በStocky ውስጥ የተቀመጠ ሽያጭ፣ ግዢ፣ ክፍያ ወይም ወጪ — በPOS ላይም ሆነ በአስተዳዳሪ ክፍሉ — ከተቀመጠ {after} በተመሳሳይ ጥያቄ ውስጥ ወደ Telegram ይላካል። የcron ግቤት የለም፣ የወረፋ ወርከር የለም፣ ገንዘብ ተቀባዩም Telegramን በፍጹም አይጠብቅም፦ መልዕክቱ በሚላክበት ጊዜ ሽያጩ አስቀድሞ ምላሽ አግኝቷል።',
'Telegram_G_Right_After' => 'ወዲያውኑ በኋላ',
'Telegram_G_B_Title' => 'የcron ግቤቱ — ለድጋሚ ሙከራዎች እና ለጀርባ ክስተቶች',
'Telegram_G_B_Body' => 'ሁለት ዓይነት መልዕክቶች በምትኩ በTelegram የራሱ ወረፋ ላይ ይጠብቃሉ፦ ያልተሳካ መላኪያ (Telegram ለአፍታ ሊደረስበት ሳይችል ሲቀር)፣ በሚቀጥሉት ጥቂት ደቂቃዎች ውስጥ እስከ ሦስት ተጨማሪ ጊዜ እንደገና የሚሞከር፤ እና ከአስተዳዳሪ ክፍሉ ውጭ የተነሱ ክስተቶች — ከWooCommerce ወይም ከShopify የገቡ ትዕዛዞች፣ የartisan ትዕዛዞች። ይህ የcron ግቤት እነሱን ይልካል፣ ሌላ ምንም አይልክም፦',
'Telegram_G_Cron_Note' => 'በየደቂቃው ትክክል ነው፦ የሚጠብቅ ነገር የሌለው ሩጫ ወዲያውኑ ይወጣል። በcPanel ላይ ይህ በ{cronJobs} ውስጥ ይገባል — {php} የቆየ ከሆነ ወደ PHP 8.2+ ሙሉ ዱካውን ይጠቀሙ። በWindows ላይ Task Schedulerን በፕሮግራም {program}፣ በነጋሪ እሴቶች {args}፣ በ{path} ውስጥ የሚጀምር አድርገው ይጠቀሙ።',
