'Telegram_G_Without_Cron' => 'ያለ cron ግቤቱ በStocky ውስጥ የተቀመጠው ሁሉ አሁንም ወዲያውኑ ይደርሳል፤ የሚያጡት ድጋሚ ሙከራዎችን እና የገቡ ትዕዛዞችን ብቻ ነው።',
