'Presta_Shop_Language_Help' => 'ሲገፋ ለምርት ስሞች የሚያገለግል የቋንቋ id (1 = የሱቁ የመጀመሪያ ቋንቋ)።',
'Presta_Push_Products_Desc' => 'የጎደሉ ቀላል ምርቶችን (ከአሁኑ ክምችታቸው ጋር) በPrestaShop ላይ ይፈጥራል። ቀድሞ የተያያዙ ምርቶች እና ዓይነት ያላቸው ምርቶች ይዘለላሉ — የምርት ዝርዝሮችን በPrestaShop ውስጥ ማስተካከልዎን ይቀጥሉ፣ ወይም የአካባቢውን ቅጂ ለማደስ ይሳቡ።',
'Presta_Pull_Products_Desc' => 'የPrestaShop ምርቶችን ያስገባል፣ ያሉትን በማጣቀሻ (SKU) ያዛምዳል እና የቀሩትን ይፈጥራል። ጥምረቶች (combinations) እንደ ወላጅ ምርታቸው ይገባሉ።',
'Presta_Reset_Product_Confirm' => 'የምርት ትስስሮች ዳግም ይጀመሩ? የትዕዛዝ ታሪክ ትስስሮቹን ይይዛል።',
'Presta_Push_Stock_Desc' => 'ለእያንዳንዱ የተያያዘ ምርት የሱቁን ክምችት (stock_availables) ያዘምናል።',
'Presta_Pull_Orders_Desc' => 'የሱቅ ትዕዛዞችን እንደ ሽያጮች (እንደ {ref} ያሉ ማጣቀሻዎች) ያስገባል፣ አዲሶቹ መጀመሪያ። ቀድሞ የገቡ እና የተሰረዙ ትዕዛዞች ይዘለላሉ፣ ስለዚህ በየጊዜው መሳብ ደህንነቱ የተጠበቀ ነው። PrestaShop webhooks የለውም — ከተጨናነቁ ጊዜያት በኋላ ይህን ያሂዱ።',
'Presta_Guide_1' => 'በPrestaShop የአስተዳደር ክፍልዎ ውስጥ {menu} ይክፈቱ እና webservice ን ያንቁ።',
'Presta_Guide_2' => 'አዲስ ቁልፍ ያክሉ፣ በ{products} እና {stock} ላይ {rw}፣ በ{orders} እና {customers} ላይ ደግሞ {view} ፈቃድ በመስጠት።',
'Presta_Guide_3' => 'የሱቁን URL እና ቁልፉን በግንኙነት ትር ላይ ይለጥፉ፣ ያስቀምጡ፣ እና {test} ያሂዱ።',
'Presta_Guide_4' => 'ሱቁ ቀድሞ ካታሎግ ካለው መጀመሪያ ምርቶችን ይሳቡ (በማጣቀሻ/SKU ይዛመዳል)፤ የጎደሉ ቀላል ምርቶችን ለመፍጠር ይግፉ።',
'Presta_Guide_5' => 'ብዛት በተቀየረ ቁጥር ክምችትን ይግፉ፣ ትዕዛዞችንም በየጊዜው ይሳቡ — PrestaShop webhooks ስለሌለው ትዕዛዞች የሚደርሱት ሲሳቡ ብቻ ነው።',
'Presta_Identity_Title' => 'የምርት መለያው ማጣቀሻው (SKU) ነው',
'Presta_Identity_Desc' => 'የStocky የምርት ኮድ ከPrestaShop ማጣቀሻ ጋር ይዛመዳል። በሁለቱም ወገን ማጣቀሻዎችን ወጥ አድርገው ይያዙ፤ ጥምረቶች (ዓይነቶች) በትዕዛዞች ውስጥ በማጣቀሻ ይዛመዳሉ ነገር ግን በዚህ ስሪት አይገፉም።',
