'Xero_Hero_Desc' => 'ደንበኞችዎን እንደ Xero እውቂያዎች እና ሽያጮችዎን እንደ ደረሰኞች ይግፉ — የባንክ መለያ ሲዋቀር ከክፍያዎች ጋር።',
