'Xero_Payment_Account_Help' => 'የባንክ መለያ ኮድ። ሲዘጋጅ የተከፈሉ ሽያጮች በደረሰኙ ላይ ክፍያም ይመዘግባሉ፤ ደረሰኞችን ብቻ ለማመሳሰል ባዶ ይተዉት።',
'Xero_Auto_Sync_Sales' => 'አዳዲስ ሽያጮችን እንደ ደረሰኞች በራስ-ሰር አመሳስል',
'Xero_Auto_Sync_Sales_Hint' => '(ሽያጮች ሲፈጠሩ ከበስተጀርባ በወረፋ ይቀመጣል)',
