'Xero_Organisation' => 'ድርጅት',
'Xero_Disconnect_Confirm' => 'የXero ድርጅት ይቋረጥ? እንደገና እስኪያገናኙ ድረስ ማመሳሰል ይቆማል።',
'Xero_Redirect_Uri_Title' => 'ለXero መተግበሪያ የRedirect URI',
'Xero_Redirect_Uri_Help' => 'በ{link} ላይ "Web app" ይፍጠሩ እና ይህን redirect URI ይመዝግቡ። ማሳሰቢያ፦ የXero መዳረሻ ቶከኖች በራስ-ሰር ይታደሳሉ፣ ነገር ግን ከ60 ቀናት በላይ ስራ ላይ ያልዋለ ግንኙነት እንደገና መገናኘት አለበት።',
'Xero_Total_Customers' => 'ጠቅላላ ደንበኞች',
'Xero_Contacts_In_Xero' => 'በXero ውስጥ ያሉ እውቂያዎች',
'Xero_Total_Sales' => 'ጠቅላላ ሽያጮች',
'Xero_Invoices_In_Xero' => 'በXero ውስጥ ያሉ ደረሰኞች',
'Xero_Payments_Recorded' => 'የተመዘገቡ ክፍያዎች',
'Xero_Push_Customers_To' => 'ደንበኞችን ወደ {name} ይግፉ',
'Xero_Push_Customers_Desc' => 'ለእያንዳንዱ ደንበኛ የXero እውቂያ ይፈጥራል ወይም ያዘምናል። ስሙ ቀድሞ በXero ውስጥ ያለ ደንበኛ ከዚያ እውቂያ ጋር ይያያዛል።',
'Xero_Push_Customers' => 'ደንበኞችን ግፋ',
'Xero_Push_Sales_Invoices' => 'ሽያጮችን እንደ ደረሰኞች ግፋ',
'Xero_Push_Invoices_Desc' => 'ለእያንዳንዱ ሽያጭ አንድ AUTHORISED ደረሰኝ ይፈጥራል (የደረሰኝ ቁጥር = የሽያጩ ማጣቀሻ)፣ ከሽያጩ የዕቃ መስመሮች እንዲሁም ከመላኪያ፣ ከቅናሽ እና ከግብር መስመሮች ጋር፣ ስለዚህ የXero ጠቅላላ ከሽያጩ ጠቅላላ ጋር ይመሳሰላል። ቀድሞ በXero ውስጥ ያሉ ሽያጮች ይዘለላሉ — ደረሰኞች በጭራሽ አይስተካከሉም። የጎደሉ እውቂያዎች በዚያው ጊዜ ይፈጠራሉ።',
'Xero_Push_Invoices' => 'ደረሰኞችን ግፋ',
'Xero_Reset_Contact_Confirm' => 'የእውቂያ ትስስሮች ዳግም ይጀመሩ? የሚቀጥለው ግፊት እንደገና ያያይዛቸዋል ወይም እንደገና ይፈጥራቸዋል።',
'Xero_Reset_Contact_Links' => 'የእውቂያ ትስስሮችን ዳግም አስጀምር',
'Xero_Guide_1' => 'በ{link} ላይ {webApp} ይፍጠሩ ({menu})።',
'Xero_Guide_2' => 'በግንኙነት ትር ላይ የሚታየውን redirect URI ይመዝግቡ።',
'Xero_Guide_3' => 'የመተግበሪያውን {clientId} ይቅዱ እና {clientSecret} ያመንጩ፤ ሁለቱንም እዚህ ይለጥፉ እና ያስቀምጡ።',
'Xero_Guide_4' => '{connect} ይጫኑ፣ ይግቡ እና የሚገናኘውን ድርጅት ይምረጡ።',
'Xero_Guide_5' => 'የመለያ ኮዶችን ያረጋግጡ፦ የሽያጭ መለያው የደረሰኝ መስመሮችን ይቀበላል፤ የተከፈሉ ሽያጮች ክፍያዎችንም እንዲመዘግቡ ከፈለጉ የባንክ መለያ ኮድ ያዘጋጁ።',
'Xero_Guide_6' => 'መጀመሪያ ደንበኞችን፣ ከዚያም ደረሰኞችን ይግፉ። የደረሰኝ ቁጥሮች የሽያጭ ማጣቀሻዎች ስለሆኑ ትስስሮች ዳግም ቢጀመሩም ተደጋጋሚዎች በXero ውድቅ ይደረጋሉ።',
'Xero_Amounts_Title' => 'መጠኖች ግብርን ጨምረው እንዳሉ ይገፋሉ',
'Xero_Amounts_Desc' => 'ደረሰኞች ሽያጩን በትክክል የሚያንጸባርቁ NoTax መስመሮችን ይጠቀማሉ (ዕቃዎች + መላኪያ − ቅናሽ + ግብር)፣ ስለዚህ የXero ጠቅላላዎች ሁልጊዜ ከStocky ጠቅላላዎች ጋር እኩል ናቸው። የሂሳብ ባለሙያዎ የግብር እና የመላኪያ መስመሮችን በXero ውስጥ ወደ ተገቢ መለያዎች እንደገና መመደብ ይችላል።',
'Xero_Org_Connected' => 'የXero ድርጅት ተገናኝቷል።',
'Jumia_Hero_Title' => 'የJumia የገበያ ቦታ ማመሳሰል',
'Jumia_Hero_Desc' => 'ዋጋዎችን እና ክምችትን ወደ Jumia Seller Center ዝርዝሮችዎ ይግፉ እና የገበያ ቦታ ትዕዛዞችን እንደ ሽያጮች ያስገቡ።',
'Jumia_Api_Url_Label' => 'API URL (የሀገርዎ Seller Center endpoint)',
'Jumia_Account_Email' => 'የመለያ Email (User ID)',
'Jumia_Api_Key' => 'API ቁልፍ',
'Jumia_Prices_Stock' => 'ዋጋዎች እና ክምችት',
'Jumia_Push_Prices_Stock_Title' => 'ዋጋዎችን እና ክምችትን ወደ Jumia ይግፉ',
'Jumia_Push_Prices_Stock_Desc' => 'ከJumia ዝርዝሩ {sku} ጋር የሚዛመድ SKU ላለው እያንዳንዱ ምርት (እና ዓይነት) የአሁኑን ዋጋ እና ብዛት ይልካል። ዝማኔዎች እንደ Seller Center feeds ይላካሉ እና ባልተመሳሰለ ሁኔታ ይተገበራሉ — የfeed ID በመዝገቦች ትር ውስጥ ይመዘገባል፣ በየዕቃው ውድቅ የተደረጉት ደግሞ በSeller Center የfeed ሁኔታ ገጽ ላይ ይታያሉ።',
'Jumia_Push_Prices_Stock' => 'ዋጋዎችን እና ክምችትን ግፋ',
'Jumia_Pull_Orders_Desc' => 'የገበያ ቦታ ትዕዛዞችን እንደ ሽያጮች (እንደ {ref} ያሉ ማጣቀሻዎች) ያስገባል፣ ከምርቶችዎ ጋር በSeller SKU ይዛመዳሉ። ቀድሞ የገቡ እና የተሰረዙ ትዕዛዞች ይዘለላሉ፣ ስለዚህ በየጊዜው መሳብ ደህንነቱ የተጠበቀ ነው። ክፍያዎች እንደተከፈሉ የሚመዘገቡት ለደረሱ ትዕዛዞች ብቻ ነው (Jumia በአብዛኛው በማድረስ ጊዜ ክፍያ (COD) ይጠቀማል)።',
'Jumia_Guide_1' => 'በJumia {sellerCenter} ውስጥ {menu} ይክፈቱ እና API ቁልፍ ያመንጩ።',
'Jumia_Guide_2' => 'የሀገርዎን API URL (ለምሳሌ {ng} ለናይጄሪያ፣ {ke} ለኬንያ፣ {eg} ለግብፅ)፣ የSeller Center መለያ Emailዎን እና ቁልፉን ያስገቡ — ከዚያም {test} ያሂዱ።',
'Jumia_Guide_3' => 'የእያንዳንዱ Jumia ዝርዝር {sku} ከStocky የምርት ኮድ ጋር እኩል መሆኑን ያረጋግጡ — ለክምችት ግፊቶችም ሆነ ለትዕዛዝ ማዛመድ የሚያገለግለው መለያ ይህ ነው።',
'Jumia_Guide_4' => 'ከክምችት ለውጦች በኋላ ዋጋዎችን እና ክምችትን ይግፉ፤ ትዕዛዞችን በየጊዜው ይሳቡ (Jumia በዚህ API ውስጥ webhooks የለውም)።',
'Jumia_Guide_5' => 'አዳዲስ ዝርዝሮችን መፍጠር በSeller Center ውስጥ ይቀራል — Jumia በምድብ የተለዩ ባህሪያትን እና የምስል ግምገማን ይጠይቃል፣ እነዚህንም በደንብ የሚያስተናግደው የራሳቸው ፖርታል ብቻ ነው።',
'Mailchimp_Hero_Title' => 'የMailchimp ታዳሚ ማመሳሰል',
'Mailchimp_Hero_Desc' => 'በእውነተኛ የደንበኛ መሠረትዎ ላይ የEmail ዘመቻዎችን ማካሄድ እንዲችሉ የMailchimp ታዳሚን በደንበኞችዎ ተሞልቶ ያቆዩ።',
'Mailchimp_Account_Audience' => 'መለያ እና ታዳሚ',
'Mailchimp_Api_Key_Ph' => 'ለምሳሌ {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} አባላት)',
'Mailchimp_Load_Audiences_Ph' => 'አንዱን ለመምረጥ ታዳሚዎችን ይጫኑ',
'Mailchimp_Load_Audiences' => 'ታዳሚዎችን ጫን',
'Mailchimp_Double_Optin_Label' => 'ድርብ ፈቃድ (Double opt-in) — አዳዲስ አባላት ከመቀላቀላቸው በፊት የማረጋገጫ Email ይደርሳቸዋል',
'Mailchimp_Double_Optin_Hint' => '(ለGDPR ይመከራል)',
'Mailchimp_Auto_Sync_Customers' => 'አዳዲስ ደንበኞችን ሲፈጠሩ በራስ-ሰር አመሳስል',
'Mailchimp_With_Email' => 'Email ያላቸው',
'Mailchimp_Push_Desc' => 'Email አድራሻ ያለውን እያንዳንዱን ደንበኛ ወደ ተመረጠው ታዳሚ ያክላል ወይም ያዘምናል (ስም እና ስልክ ጨምሮ)። ያሉ አባላት የምዝገባ ሁኔታቸውን ይይዛሉ — ምዝገባውን የሰረዘ ማንም እንደገና አይመዘገብም። Email የሌላቸው ደንበኞች አይካተቱም።',
'Mailchimp_Double_Optin_Off_Title' => 'ድርብ ፈቃድ ጠፍቷል',
'Mailchimp_Double_Optin_Off_Desc' => 'አዳዲስ አባላት ያለ ማረጋገጫ Email እንደተመዘገቡ ይታከላሉ። ይህን የሚያደርጉት የማስታወቂያ መልዕክቶችን ለመቀበል ቀድመው ለተስማሙ ደንበኞች ብቻ ይሁን።',
'Mailchimp_Guide_1' => 'በMailchimp ውስጥ {menu} ይክፈቱ እና ቁልፍ ይፍጠሩ (በ{suffix} ያበቃል — ያ ቅጥያ የእርስዎ ዳታሴንተር ነው)።',
'Mailchimp_Guide_2' => 'ቁልፉን እዚህ ይለጥፉ፣ ያስቀምጡ፣ ከዚያም {load} ይጫኑ እና የሚሞላውን ታዳሚ ይምረጡ።',
'Mailchimp_Guide_3' => 'ደንበኞችዎ ለማስታወቂያ Emailዎች ቀድመው ካልተስማሙ በስተቀር {doubleOptIn} በርቶ ይተዉት።',
'Mailchimp_Double_Optin_Term' => 'ድርብ ፈቃድ (double opt-in)',
'Mailchimp_Guide_4' => 'ለመጀመሪያ ሙሌት {push} ያሂዱ፤ አዳዲስ ደንበኞች በራስ-ሰር እንዲቀላቀሉ {autoSync} ያብሩ።',
'Mailchimp_Auto_Sync_Term' => 'ራስ-ሰር ማመሳሰል',
'Mailchimp_Consent_Title' => 'ፈቃድ አስፈላጊ ነው',
'Mailchimp_Consent_Desc' => 'ለማስታወቂያ ፈጽሞ ያልተስማሙ ሰዎችን Email ማድረግ GDPR/CAN-SPAM ሊጥስ እና የMailchimp መለያዎ እንዲታገድ ሊያደርግ ይችላል። ድርብ ፈቃድ ማረጋገጫውን ወደ Mailchimp ያስተላልፋል — ደህንነቱ የተጠበቀው ነባሪ ይህ ነው።',
'Mailchimp_No_Audiences' => 'በዚህ መለያ ላይ ምንም ታዳሚ አልተገኘም።',
'GSheets_Hero_Title' => 'የGoogle Sheets ኤክስፖርቶች',
'GSheets_Hero_Desc' => 'ሽያጮችዎን፣ ምርቶችዎን እና ደንበኞችዎን ወደ ቀጥታ የGoogle ስፕሬድሺት ይላኩ — ለእያንዳንዳቸው አንድ ትር፣ ሲጠየቅ የሚታደስ።',
