'GSheets_Export_Desc' => 'እያንዳንዱ ኤክስፖርት ትሩን ከባዶ እንደገና ይጽፋል (ራስጌ + ሁሉም ረድፎች)፣ ስለዚህ ሉሁ ሁልጊዜ የተሟላ እና ወቅታዊ ቅጽበታዊ እይታ ነው። ትላልቅ የመረጃ ስብስቦች በክፍል ይላካሉ — ቆጣሪው እስኪቆም ድረስ ገጹን ክፍት ይተዉት።',
