'GSheets_Products_Desc' => 'ሙሉ ካታሎጉ ከዋጋዎች፣ ከወጪዎች እና ከአሁኑ የክምችት ብዛት ጋር።',
'GSheets_Customers_Desc' => 'ሁሉም ደንበኞች ከእውቂያ ዝርዝሮቻቸው ጋር።',
'GSheets_Guide_1' => 'በ{link} ላይ ፕሮጀክት ይፍጠሩ እና {api} ያንቁ ({menu})።',
'GSheets_Guide_2' => '{consent} ያዋቅሩ (External)። በ"Testing" ላይ እስካለ ድረስ የGoogle መለያዎን እንደ የሙከራ ተጠቃሚ ያክሉ — በሙከራ ሁነታ የrefresh ቶከኖች ከ7 ቀናት በኋላ ጊዜያቸው እንደሚያልፍ ልብ ይበሉ፣ ስለዚህ ለቋሚ ግንኙነት መተግበሪያውን {publish}።',
