'GSheets_Guide_5' => 'በአዝራሩ ስፕሬድሺት ይፍጠሩ (ወይም የGoogle መለያዎ ማስተካከል የሚችለውን የአንዱን URL ይለጥፉ)፣ ከዚያም ኤክስፖርቶቹን ያሂዱ።',
'GSheets_Snapshots_Title' => 'ቅጽበታዊ እይታዎች እንጂ ቀጥታ ማመሳሰል አይደለም',
