'Shopify_Stock_Lag_Title' => 'ክምችት Shopify የሚደርሰው የክምችት ግፊት ደረጃው ሲሄድ ብቻ ነው',
'Shopify_Stock_Lag_Desc' => 'በመደብሩ የተደረገ ሽያጭ እስከዚያ ድረስ ለሱቁ አይታይም — እስከ {n} ደቂቃ፣ ስለዚህ የመጨረሻው ዕቃ አሁንም በመስመር ላይ ሁለት ጊዜ ሊሸጥ ይችላል። {setting} ያብሩ እና እያንዳንዱ ሽያጭ፣ መመለሻ እና ማስተካከያ በምትኩ በሰከንዶች ውስጥ ይላካል።',
'Shopify_Turn_It_On' => 'አብራው',
'Shopify_Stock_Also_Pushed' => 'ከላይ ያለውን ደረጃ ሳይጠብቅ ክምችት ከማንኛውም ሽያጭ፣ መመለሻ ወይም ማስተካከያ በኋላ በሰከንዶች ውስጥም ይገፋል።',
'Shopify_Sync_History' => 'የማመሳሰል ታሪክ',
'Shopify_Nothing_Run_Store' => 'ለዚህ ሱቅ ምንም አልተሄደም',
'Shopify_Hook_Msg_Client' => 'ከታች “Register webhooks” ይጫኑ — በShopify ውስጥ ምንም ማስገባት አያስፈልግም።',
'Shopify_Hook_Msg_Token' => 'ከታች “Register webhooks” ይጫኑ፣ እና የመተግበሪያውን API secret key በሱቅ ቅንብሮች ውስጥ እንደ ፊርማ ሚስጥር ይለጥፉ።',
'Shopify_Hook_Note_Register' => 'መመዝገብ በShopify ውስጥ ምዝገባዎቹን ይፈጥራል እና በራስ-ሰር ወደዚህ አድራሻ ያመላክታቸዋል። በShopify → Settings → Notifications → Webhooks ስር በእጅ አያክሉት፦ እነዚያ በተለየ ሚስጥር ስለሚፈረሙ እያንዳንዱ መላክ ውድቅ ይደረጋል።',
'Shopify_Hook_Verified_Client' => 'መላኮች የሚረጋገጡት ቀድሞ በተቀመጠው የመተግበሪያው client secret ነው።',
'Shopify_Hook_Signature_Required' => 'ትክክለኛ ፊርማ የሌላቸው መላኮች ውድቅ ይደረጋሉ፣ ስለዚህ webhooks ማንኛውንም ነገር ከማድረጋቸው በፊት ሚስጥሩ መዘጋጀት አለበት።',
'Shopify_Hook_Retries' => 'Shopify 2xx እስኪያገኝ ድረስ እንደገና ይሞክራል፣ እያንዳንዱ መላክም አንድ ጊዜ ብቻ ይመዘገባል — የተደጋገመ ክስተት ምንም ውጤት የለውም፣ ተደጋጋሚ ትዕዛዝ አይፈጥርም።',
