'Shopify_Could_Not_Remove_Sub' => 'ያንን ምዝገባ ማስወገድ አልተቻለም',
'Shopify_Could_Not_Load_Store' => 'ይህን ሱቅ መጫን አልተቻለም',
'Shopify_G_Lead_Store' => 'ይህ ሱቅ ራሱን ተመሳስሎ ለማቆየት የሚያስፈልገው። እዚህ ያለው ሁሉ ለዚህ ሱቅ የተለየ ነው — መንገዶቹ እና idዎቹ እውነተኛ ስለሆኑ ትዕዛዞቹ በቀጥታ ወደ አገልጋዩ ሊቀዱ ይችላሉ።',
'Shopify_G_Lead_Generic' => 'የShopify ሱቅ ራሱን ከERP ጋር እንዴት ተመሳስሎ እንደሚያቆይ። የራሱን ሁኔታ ለማየት ከላይ ሱቅ ይምረጡ፣ ወይም እንዳለ ያንብቡት — የcron መስመሩ እና የwebhook URL ምንም ዓይነት ሱቅ ቢያገናኙ ተመሳሳይ ናቸው።',
'Shopify_G_Ways_Note' => 'አብዛኞቹ ሱቆች ሁለቱንም ያሄዳሉ፦ የመጀመሪያው ሱቁን በየደቂቃው ወቅታዊ ያደርጋል፣ ሁለተኛው የመጀመሪያው ያመለጠውን ይይዛል — ፈጽሞ ያልደረሰ webhook፣ በቀጥታ በShopify አስተዳዳሪ ውስጥ የተደረገ ማስተካከያ፣ ጣቢያው የተቋረጠበት ምሽት።',
'Shopify_G_Both_Need' => 'ሁለቱም መንገዶች መጀመሪያ ይህን ይፈልጋሉ',
'Shopify_G_Credentials' => 'የShopify መግቢያ መረጃዎች',
'Shopify_G_Cred_Intro' => 'ከጃንዋሪ 2026 ጀምሮ Shopify በአስተዳዳሪ ክፍሉ ውስጥ ብጁ መተግበሪያዎችን ስለማይፈጥር ሁለት ዓይነት ግንኙነቶች አሉ፦',
'Shopify_G_Cred_DevDash' => '{app} (አሁን የሚገናኝ ማንኛውም ሱቅ) — {path}። ይህ ሱቅ ለሚያመሳስለው የAdmin API ፈቃዶችን (scopes) ይስጡ፣ መተግበሪያውን በሱቁ ላይ ይጫኑ፣ ከዚያም {clientId} እና {clientSecret} ን ከመተግበሪያው የቅንብሮች ገጽ ወደ {where} ይቅዱ። ERP ው እነሱን በመዳረሻ ቶከን ራሱ ይለውጣል እና በየ24 ሰዓቱ ጊዜው ከማለፉ በፊት ያድሰዋል። client secret ው webhooks ንም ይፈርማል፣ ስለዚህ ሌላ ምንም አያስፈልግም። መተግበሪያው እና ሱቁ በአንድ የShopify ድርጅት ውስጥ መሆን አለባቸው።',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard መተግበሪያ',
'Shopify_G_Cred_Legacy' => '{app} (ከ2026 በፊት በአስተዳዳሪው ውስጥ የተፈጠረ) — በ{token} ({prefix}) እና በ{secret} እንደ Webhook መፈረሚያ ሚስጥር ሳይለወጥ መስራቱን ይቀጥላል። ከቶከኑ ጋር አንድ አይነት እሴት አይደለም፤ ሁለቱን ማቀያየር Webhook ዎች ውድቅ የሚደረጉበት የተለመደ ምክንያት ነው።',
'Shopify_G_Legacy_App' => 'የቆየ ብጁ መተግበሪያ',
'Shopify_G_API_Secret_Key' => 'API ሚስጥራዊ ቁልፍ',
'Shopify_G_Stored' => 'ተቀምጧል',
'Shopify_G_Missing_Refused' => 'የለም — መላኪያዎች ውድቅ ይደረጋሉ',
'Shopify_G_Where_Data_Desc' => '{path} ይህ ሱቅ ክምችቱን የሚሸጥበት የERP መጋዘን እና ያ ክምችት የሚጻፍበት የShopify ቦታ። የክምችት ማመሳሰልም ሆነ የትዕዛዝ ማስገባት ያለ እነዚህ አይሰሩም።',
'Shopify_G_Currently' => 'አሁን፦ መጋዘን {warehouse}፣ ቦታ {location}',
'Shopify_G_Not_Set_Lower' => 'አልተዘጋጀም',
'Shopify_G_Ready' => 'ዝግጁ',
'Shopify_G_Incomplete' => 'ያልተሟላ',
'Shopify_G_Manual_Syncs' => 'በእጅ የሚጀምሯቸው ማመሳሰሎች',
'Shopify_G_Manual_Desc' => 'ከ{centre} የተጀመረ ማመሳሰል ወዲያውኑ ምላሽ ይሰጣል እና ከበስተጀርባ ይሰራል፤ እያንዳንዱ ካለፈው የቆመበት የሚቀጥል አጫጭር ክፍሎች ሆኖ። ረጅም የድር ጥያቄዎችን የሚያቋርጥ ማስተናገጃ (LiteSpeed፣ nginx፣ ሎድ ባላንሰር) ትልቅ ካታሎግን በግማሽ አያቋርጠውም፤ ገጹን መዝጋትም አያስቆመውም። ለዚህ የሚያስፈልገው ሰራተኛ (worker) አንድ ተጨማሪ የcron መስመር ነው፦',
'Shopify_G_Cron_Copied' => 'የcron መስመር ተቀድቷል',
'Shopify_G_Manual_Note' => 'ያለ እሱ ማመሳሰል አሁንም ይጠናቀቃል፤ ነገር ግን የማመሳሰያ ማዕከል ገጹ ክፍት እስከሆነ ድረስ ብቻ ነው፦ በጥቂት ሰከንዶች ውስጥ ምንም ሰራተኛ ሩጫውን ካልወሰደ፣ ገጹ ራሱ አንድ አጭር ጥያቄ በአንድ ጊዜ እያቀረበ ይቀጥለዋል። በWindows ላይ Task Scheduler በየደቂቃው ይጠቀሙ፦ ፕሮግራም {program}፣ ነጋሪ እሴቶች {args}፣ የሚጀመርበት {dir}።',
'Shopify_G_Then_Pick' => 'ከዚያ እንዴት እንደሚጣጣም ይምረጡ',
'Shopify_G_Right_Away' => 'ወዲያውኑ',
'Shopify_G_Stock_Live' => 'ክምችት በቀጥታ',
'Shopify_G_Stock_Not_Live' => 'ክምችት በቀጥታ አይደለም',
'Shopify_G_Realtime_Lead' => 'እያንዳንዱ ለውጥ እንደተከሰተ በሰከንዶች ውስጥ ይላካል። ሁለት ግማሾች አሉ፣ እና የተለያዩ ማብሪያዎች ናቸው፦ {webhooks} የሱቁን የራሱን ክስተቶች ያስገባሉ፣ {push} ደግሞ ክምችትን ይልካል።',
'Shopify_G_Webhooks_Lower' => 'Webhook ዎች',
'Shopify_G_Instant_Push_Lower' => 'ፈጣን የክምችት መላክ',
'Shopify_G_Webhooks_In' => 'Webhook ዎች — ሱቁ → ERP',
'Shopify_G_Webhooks_Desc' => 'በShopify የተደረጉ ትዕዛዞች፣ የትዕዛዝ ሁኔታ ለውጦች እና የምርት፣ የደንበኛ እና የክምችት ማስተካከያዎች። ሱቁን ይክፈቱ እና በ{tab} ላይ {button} ይጫኑ — ሁለት ጊዜ መጫን ችግር የለውም። Shopify የሚልከው ወደ፦',
'Shopify_G_Webhooks_Tab' => 'Webhook ዎች ትር',
'Shopify_G_Webhooks_Note' => 'አድራሻው ከበይነመረብ በHTTPS ተደራሽ መሆን አለበት — Shopify ወደ {localhost} ወይም ወደ {test} ዶሜይን አይልክም። እያንዳንዱ መላኪያ አንድ ጊዜ ብቻ ይመዘገባል፤ ስለዚህ የShopify ድጋሚ ሙከራዎች የተባዛ ትዕዛዝ መፍጠር አይችሉም፣ ያልተሳካውም እንደገና ሊሄድ ይችላል። ከደረጃ 1 የመፈረሚያ ሚስጥሩ እስኪቀመጥ ድረስ መላኪያዎች ውድቅ ይደረጋሉ።',
'Shopify_G_Instant_Out' => 'ፈጣን የክምችት መላክ — ERP → ሱቁ',
'Shopify_G_Setting_Missed' => 'ሰዎች የሚዘነጉት ቅንብር ይህ ነው',
'Shopify_G_Pos_Not_Auto' => 'የPOS ሽያጭ በራሱ ወደ Shopify {not}ደርስም። ጠፍቶ ከተተወ ሱቁ የሚያውቀው በሚቀጥለው የክምችት መላኪያ ደረጃ ብቻ ነው — በዚያ ጊዜ ውስጥ በካውንተሩ አስቀድመው የሸጡትን እቃ ሊሸጥ ይችላል።',
'Shopify_G_Not' => 'አይ',
'Shopify_G_Tick_Push' => 'በ{where} ላይ {setting}ን ምልክት ያድርጉ። ማዋቀሩ ይኸው ነው — ሰራተኛ (worker) ወይም cron አያስፈልግም። ከዚያ እያንዳንዱ ሽያጭ፣ መመለሻ እና ማስተካከያ ሽያጩ እንደተቀመጠ የነዚያን ምርቶች ብቻ መላኪያ ይልካል፤ ሃያ መስመር ያለው ሽያጭ አንድ መላኪያ እንጂ ሃያ አይጠይቅም። ካሽ ሬጂስተሩ በፍጹም አይጠብቀውም።',
'Shopify_G_This_Store' => 'ይህ ሱቅ፦',
'Shopify_G_Push_On' => 'በርቷል — ክምችት ሲቀየር ይላካል',
'Shopify_G_Push_Off' => 'ጠፍቷል — ክምችት በመርሐግብር ብቻ',
'Shopify_G_Push_Note' => 'የሚላኩት አስቀድሞ የShopify ትስስር ያላቸው ምርቶች ብቻ እና በዚህ ሱቅ መጋዘን ውስጥ ያሉ እንቅስቃሴዎች ብቻ ናቸው። የጅምላ ሥራዎች — ምርት መሰረዝ፣ መጋዘንን ዳግም ማስጀመር — ክስተት ሳያስነሱ ክምችትን ይጽፋሉ፤ ይህም የመርሐግብር የክምችት ደረጃውንም ማቆየት ከሚያስፈልግበት ምክንያቶች አንዱ ነው።',
'Shopify_G_Nothing_Install' => 'ሌላ የሚጫን ነገር የለም',
'Shopify_G_No_Worker_Note' => 'ሁለቱም ግማሾች የወረፋ ሰራተኛ (queue worker) ወይም የcron መግቢያ አያስፈልጋቸውም። የሚመጣ Webhook Shopify በሚያቀርበው ጥያቄ ውስጥ ይስተናገዳል፤ የሚወጣ የክምችት መላኪያ ሽያጩን ባስተናገደው ተመሳሳይ ሂደት ውስጥ ምላሹ ከተመለሰ {after} ይሰራል — ስለዚህ ካሽ ሬጂስተሩ Shopifyን በፍጹም አይጠብቅም፣ ምላሽ መስጠት ያቆመ ሱቅ ደግሞ ከአስር ሰከንድ በኋላ ይተዋል እና ለሚቀጥለው የመርሐግብር የክምችት መላኪያ ይቀራል።',
'Shopify_G_After' => 'በኋላ',
'Shopify_G_Artisan_Note' => 'አንድ ልዩ ሁኔታ፦ በartisan ትዕዛዝ የተደረገ የክምችት ለውጥ የሚከተለው ምላሽ ስለሌለው በምትኩ በ{queue} ወረፋ ላይ ይቀመጣል። እነዚያም በፍጥነት እንዲወጡ ከፈለጉ ያንን ወረፋ ያሂዱ፦',
'Shopify_G_On_Schedule' => 'በመርሐግብር',
'Shopify_G_On_Lower' => 'በርቷል',
'Shopify_G_Off_Lower' => 'ጠፍቷል',
'Shopify_G_Scheduled_Lead' => 'ሁሉም ነገር በየተወሰነ ጊዜ በሁለቱም አቅጣጫዎች እንደገና ይፈተሻል። ከቅጽበታዊው ቀርፋፋ ነው፤ ነገር ግን ፈጣን መላክን በማይጠቀሙ ሱቆች ላይ ክምችትን የሚልከው፣ ያመለጠ Webhookን የሚይዘው እና ሙሉ ካታሎግን ለማንቀሳቀስ ብቸኛው መንገድ እሱ ነው።',
'Shopify_G_Cron_Entry' => 'የcron መግቢያው',
'Shopify_G_Cron_Entry_Desc' => 'ያለ እሱ ምንም በመርሐግብር የተያዘ ነገር አይሰራም። አንድ መስመር፣ ለዚህ ሞጁል ብቻ — በመርሐግብር እንዲሰሩ ከመረጧቸው ሌሎች ነገሮች ጎን ያክሉት፦',
'Shopify_G_Cron_Note' => 'በየአምስት ደቂቃው እቅድ ሊጠቀምበት የሚችለው ዝቅተኛው ጥራት ነው፤ ምክንያቱም አምስት ደቂቃ አጭሩ የደረጃ ክፍተት ነው። ከዚያ የሰፋ መግቢያ ዝቅተኛው ወሰን ይሆናል — በ{example}፣ ለ5 ደቂቃ የተዘጋጀ ደረጃ በየ15 ይሰራል። በWindows ላይ Task Scheduler ይጠቀሙ፦ ፕሮግራም {program}፣ ነጋሪ እሴቶች {args}፣ የሚጀመርበት {dir}።',
'Shopify_G_Switch_On_Plan' => 'ያብሩት፣ እና እቅዱን ይምረጡ',
'Shopify_G_Plan_Desc' => '{where} ማብሪያው cron ጨርሶ መስራት ይችል እንደሆነ ይወስናል፤ እቅዱ ደግሞ ምን እንደሚሰራ ይወስናል። አንድ {step} በአንድ አቅጣጫ ያለ አንድ አካል ሲሆን የራሱ ክፍተት አለው — {first}፣ {second}። ነባሪው ክፍተት የራሱን ሳጥን ባዶ በሚተው ማንኛውም ደረጃ ጥቅም ላይ ይውላል።',
'Shopify_G_Step_Lower' => 'ደረጃ',
'Shopify_G_Plan_Note' => 'እቅዱን ባዶ ከተዉት ሱቁ በነባሪው ክፍተት ትዕዛዞችን ያመጣል እና ክምችትን ይልካል፤ ይህም አብዛኞቹ ሱቆች የሚፈልጉት ነው። ትዕዛዞች የሚመጡት ብቻ ናቸው፦ ደንበኛ ትዕዛዝ የሚያስገባው በShopify ነው።',
'Shopify_G_Schedule_On' => 'መርሐግብር በርቷል',
'Shopify_G_Schedule_Off' => 'መርሐግብር ጠፍቷል — በእጅ ብቻ',
'Shopify_G_When_Step_Runs' => 'አንድ ደረጃ በትክክል መቼ ይሰራል',
'Shopify_G_When_Note' => 'አንድ ደረጃ የሚደርሰው ያው ደረጃ ለመጨረሻ ጊዜ {started}በት ጊዜ ጀምሮ ከክፍተቱ የበለጠ ጊዜ ሲያልፍ ነው፤ ይህም ከሩጫ ታሪክ ይነበባል። ስለዚህ በእጅ የሚጀምሩት ማመሳሰል ቀጣዩን ራስ-ሰር ያራዝመዋል፣ ያለማቋረጥ የሚወድቅ ደረጃ ደግሞ በእያንዳንዱ ምት ሳይሆን በክፍተቱ እንደገና ይሞከራል። የሱቁ አጠቃላይ እይታ የእያንዳንዱን ደረጃ የመጨረሻ ሩጫ፣ ቀጣይ የሚደርስበትን ጊዜ እና ሲታገድ የታገደበትን ምክንያት ያሳያል። የመጀመሪያውን የካታሎግ መላኪያ በመርሐግብር ከማስቀመጥዎ በፊት በእጅ ያሂዱት — መጀመሪያ በ{dryRun}።',
'Shopify_G_Started_Lower' => 'የተጀመረ',
'Shopify_G_Where_Setting' => 'እያንዳንዱ ቅንብር የት ይገኛል',
'Shopify_G_Where_Setting_Note' => 'እነዚህ ሁሉ በነባር ሱቅ ላይ ናቸው፦ {path}፣ ከዚያ እርሳሱ (ወይም በሱቁ የራሱ ገጽ ላይ {edit})።',
'Shopify_G_Product_Images' => 'የምርት ምስሎች',
'Shopify_G_Img_1' => 'ምስሎች ከምርቱ ጋር በ{push} ይወጣሉ — ዋናው ምስል መጀመሪያ፣ ከዚያ ጋለሪው፣ ከዚያ የራሱ ምስል ላለው እያንዳንዱ ዓይነት አንድ፣ እስከ ሃምሳ ድረስ።',
'Shopify_G_Products_Push' => 'የምርቶች መላኪያ',
'Shopify_G_Img_2' => 'የዓይነት ምስል ከምርቱ ጋር ይሰቀላል ከዚያም {assigned}፤ Shopify የሚቀርጸው እንዲህ ነው፦ አንድ ዓይነት ከምርቱ ምስሎች አንዱን ያመለክታል። ዋናውን ምስል እንደገና የሚጠቀም ዓይነት ምስሉን ሁለት ጊዜ አይሰቅልም።',
'Shopify_G_Assigned' => 'ለዚያ ዓይነት ይመደባል',
'Shopify_G_Img_3' => 'እንደ ፋይል የተቀመጠ ምስል ወደ Shopify {uploaded} እንጂ አይያያዝም፤ ስለዚህ ይህ ጭነት ከበይነመረብ ተደራሽ ባይሆንም ይሰራል። እንደ ተለጠፈ ሊንክ የታከለ ምስል ለShopify በዚያው URL ይሰጣል፤ ይህም በይፋ ተደራሽ መሆን አለበት።',
'Shopify_G_Uploaded' => 'ይሰቀላል',
'Shopify_G_Img_4' => 'እንደገና የሚላኩት በእርግጥ ሲቀየሩ ብቻ ነው — ዋጋን ብቻ የሚቀይር መላኪያ የሱቁን ምስሎች አይነካም፤ ምክንያቱም እነሱን መላክ ሙሉውን ስብስብ ይተካል።',
'Shopify_G_Img_5' => 'በERP ውስጥ ምስልን ማስወገድ በShopify ውስጥ {not}ሰርዘውም። እዚያም ይሰርዙት፣ አለበለዚያ ሱቁ ማሳየቱን ይቀጥላል።',
'Shopify_G_Commands' => 'ማወቅ የሚገባቸው ትዕዛዞች',
'Shopify_G_Command_Copied' => 'ትዕዛዙ ተቀድቷል',
'Shopify_G_Foot' => 'እያንዳንዱ ማመሳሰል ወደ {logs} ይጽፋል፤ የእያንዳንዱ ሱቅ አጠቃላይ እይታ ደግሞ እያንዳንዱ ደረጃ ለመጨረሻ ጊዜ መቼ እንደሰራ፣ ቀጥሎ መቼ እንደሚደርስ እና የሆነ ነገር ሲያግደው ምን እንደሚያግደው ያሳያል። ማመሳሰል የጠበቁትን ሳያደርግ ሲቀር መጀመሪያ የሚያዩት እዚያ ነው።',
