'StoreAdm_PG_Intro_Msg' => 'PayPal፣ Paystack፣ Flutterwave፣ Razorpay፣ bKash እና SSLCommerz ጥቅም ላይ የሚውሉት በኦንላይን ሱቅ ክፍያ መፈጸሚያ (checkout) ላይ ብቻ ነው።',
'StoreAdm_PG_Intro_Desc' => 'የStripe ቁልፎች በአጠቃላይ የሚጋሩ ናቸው (አስተዳዳሪው እና ኦንላይን ሱቁ አንድ አይነት የStripe ውህደት ይጠቀማሉ)። እያንዳንዱ ትር ዘዴውን ለኦንላይን ሱቅ ክፍያ መፈጸሚያ ያበራል ወይም ያጠፋል፤ ከመስመር ውጭ ክፍያዎች ከስርዓቱ ውጭ የሚከፈሉትን ዘዴዎች ይይዛል።',
