'StoreAdm_PG_Cards_Off_Desc' => 'ቁልፎችዎ ተጠብቀዋል — የኦንላይን ሱቅ ክፍያ መፈጸሚያው መልሰው እስኪያበሩት ድረስ የካርድ አማራጩን ማቅረብ ብቻ ያቆማል።',
