'StoreAdm_PG_Paystack_Test_Live' => 'ሙከራ ወይም ቀጥታ የሚወሰነው በቁልፍ ጥንዱ ነው፦ {test} ቁልፎች በሙከራ ሁነታ ይሰራሉ፣ {live} ቁልፎች እውነተኛ ካርዶችን ያስከፍላሉ — የተለየ የsandbox ማብሪያ የለም።',
'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook URL (አማራጭ ተጠባባቂ — በPaystack ዳሽቦርድ ላይ በSettings → API Keys & Webhooks ስር ያዘጋጁት፤ ጥያቄዎች በሚስጥራዊ ቁልፍዎ በHMAC ይረጋገጣሉ)፦',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'በኦንላይን ሱቅ ክፍያ መፈጸሚያ ካርዶችን፣ የባንክ ዝውውሮችን እና የሞባይል ገንዘብን ለመቀበል Paystackን ያብሩ እና ይፋዊ እና ሚስጥራዊ ቁልፎችዎን (ከ{site} → Settings → API Keys) ያስገቡ።',
'StoreAdm_PG_Secret_Hash_Opt' => 'ሚስጥራዊ ሃሽ (Webhook ዎች፣ አማራጭ)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'በFlutterwave ዳሽቦርድ ላይ በSettings → Webhooks ስር ያዘጋጁት ሚስጥራዊ ሃሽ፤ የሚመጡ Webhook ዎች የ{header} ራስጌያቸው ካልተዛመደ ውድቅ ይደረጋሉ።',
'StoreAdm_PG_Flutterwave_Info' => 'Flutterwave v3 APIን ከክላሲክ ቁልፎች ጋር ይጠቀማል። ሙከራ ወይም ቀጥታ የሚወሰነው በቁልፍ ጥንዱ ነው ({keys} ወይም የቀጥታ ቁልፎች) — የተለየ የsandbox ማብሪያ የለም። የሱቁ ምንዛሪ በFlutterwave መለያዎ ላይ መንቃት አለበት።',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'Webhook URL (አማራጭ ተጠባባቂ — በFlutterwave ዳሽቦርድ ላይ ከላይ ካለው ሚስጥራዊ ሃሽ ጋር ያዘጋጁት)፦',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'በኦንላይን ሱቅ ክፍያ መፈጸሚያ ካርዶችን፣ የሞባይል ገንዘብን እና የባንክ ዝውውሮችን ለመቀበል Flutterwaveን ያብሩ እና የv3 ይፋዊ እና ሚስጥራዊ ቁልፎችዎን (ከ{site} → Settings → API) ያስገቡ።',
