'Cr_Guide_S_booked' => 'ኩሪየሩ ትዕዛዙን ይዟል፤ እስካሁን ማንም አልወሰደውም። ማስያዝ ሊሰረዝ የሚችለው አሁን ብቻ ነው።',
'Cr_Guide_S_picked_up' => 'ኩሪየሩ እሽጉን ወስዷል።',
'Cr_Guide_S_in_transit' => 'በማዕከላት መካከል በመጓዝ ላይ፣ በጉምሩክ ውስጥ ወይም ተይዟል።',
'Cr_Guide_S_out_for_delivery' => 'ዛሬ ከአድራሹ ጋር ነው።',
'Cr_Guide_S_failed_attempt' => 'ቤት የለም፣ ተቀባይነት አላገኘም ወይም የተሳሳተ አድራሻ። ኩሪየሩ እንደገና ይሞክራል ወይም ይመልሰዋል።',
'Cr_Guide_S_delivered' => 'ለደንበኛው ተሰጥቷል። የCOD መጠን በኩሪየሩ እንደተሰበሰበ ይቆጠራል።',
'Cr_Guide_S_returning' => 'ወደ እርስዎ በመመለስ ላይ ነው።',
'Cr_Guide_S_returned' => 'ወደ እርስዎ ተመልሷል፦ ለመገምገም በመመለሻዎች ውስጥ ይጠብቃል፣ ወይም በራስ-ሰር ወደ ክምችት ይመለሳል።',
'Cr_Guide_S_cancelled' => 'ማስያዙ ተሰርዟል።',
'Cr_Guide_T_Booking' => 'ትዕዛዞችን ማስያዝ',
'Cr_Guide_B_Booking' => 'ወደ ኩሪየር ላክ ቅጹን ከሽያጩ ይሞላል፦ ተቀባይ፣ አድራሻ፣ አሁንም ያልተከፈለውን መጠን እንደ COD፣ እና የምርቶቹን ክብደት። የራሳቸው የከተሞች ዝርዝር ያላቸው ኩሪየሮች መምረጫ ያሳያሉ፣ ምርጫዎም ለዚያ ከተማ ይታወሳል። አሰባሳቢዎች፣ DHL፣ FedEx፣ UPS እና Lalamove ተመኖችን አወዳድር ያቀርባሉ፦ ዋጋ ይምረጡ፣ አስይዝ ይገዛዋል። ብዙ ሽያጮች ከሽያጮች ዝርዝር በአንድ ጊዜ ሊያዙ ይችላሉ።',
'Cr_Guide_T_Cod' => 'በማድረስ ጊዜ ክፍያ (COD)',
'Cr_Guide_B_Cod' => 'የCOD እሽግ ከአልተሰበሰበም ወደ በኩሪየር ተሰብስቧል (በማድረስ ጊዜ) ከዚያም ለእርስዎ ተከፍሏል ይሸጋገራል። ክፍያዎችን የሚያሳውቁ ኩሪየሮች የመጨረሻውን እርምጃ ራሳቸው ያንቀሳቅሳሉ፤ ለሌሎቹ COD አዘምን ይጠቀሙ። በኩሪየር ቅንብሮች ውስጥ መለያ ከተመረጠ ክፍያው በሽያጩ ላይ እንደ ክፍያ ይመዘገባል። እሽጉ ከተጠናቀቀ በኋላ የኩሪየር ክፍያዎች እንደ ወጪ ሊቀመጡ ይችላሉ።',
'Cr_Guide_T_Returns' => 'የተመለሱ እሽጎች',
'Cr_Guide_B_Returns' => 'በነባሪ የተመለሰ እሽግ በኩሪየር ጭነቶች ውስጥ ለመገምገም በመመለሻዎች ስር ይጠብቃል። ወደ ክምችት መልስ ለጠቅላላው ትዕዛዝ የሽያጭ መመለሻ ይፈጥርና ዕቃዎቹን ወደ ክምችት ይመልሳል፤ አሰናብት ምንም ነገር አይመልስም፣ ለተበላሹ ወይም ለጠፉ እሽጎች። በምትኩ የኩሪየር ቅንብሮች በራስ-ሰር ወደ ክምችት እንዲመልሱ ማድረግ ይቻላል።',
'Cr_Guide_T_Customers' => 'የደንበኛ መልዕክቶችና የመከታተያ ገጽ',
'Cr_Guide_B_Customers' => 'በኩሪየር ቅንብሮች ውስጥ ያሉ የደንበኛ ማሳወቂያዎች እርስዎ ምልክት ባደረጓቸው ሁኔታዎች SMS፣ Email ወይም WhatsApp ይልካሉ፣ እያንዳንዳቸው ለአንድ እሽግ አንድ ጊዜ፣ በራስዎ ጽሑፍ። በኦንላይን ሱቅዎ ውስጥ ያለው የመከታተያ ገጽ ደንበኞች እሽግን በመከታተያ ቁጥር፣ ወይም በትዕዛዝ ቁጥርና በስልክ እንዲከታተሉ ያስችላል። ብዙ ጊዜ እሽጎችን የሚመልሱ ደንበኞች ሲያስይዙ የመመለስ ስጋት ምልክት ያገኛሉ።',
'Cr_Guide_T_Labels' => 'መለያ ምልክቶች',
'Cr_Guide_B_Labels' => 'መለያ ምልክት አትም ኩሪየሩ የራሱን መለያ ምልክት ካወጣ (PDF፣ አገናኝ ወይም ምስል) እሱን ይሰጣል፣ ካልሆነ ግን የመከታተያ ባርኮድና የሚሰበሰበውን መጠን የያዘ የStocky መለያ ምልክት ይሰጣል። ለማተም ለዚህ ጣቢያ ብቅ-ባይ መስኮቶችን ይፍቀዱ። DHL፣ FedEx እና UPS መለያ ምልክታቸውን የሚሰጡት አንድ ጊዜ ብቻ፣ በማስያዝ ጊዜ ነው፣ Stocky ደግሞ ለድጋሚ ህትመት ያስቀምጠዋል።',
'Cr_Guide_T_Faq' => 'ችግር መፍቻ',
'Cr_Guide_Q_Test' => 'የግንኙነት ሙከራ አልተሳካም',
'Cr_Guide_A_Test' => 'የሙከራ ሁነታ ቁልፎች ከሙከራ ሁነታ ጋር፣ የቀጥታ ቁልፎች ደግሞ ከቀጥታ ጋር ይሄዳሉ፤ የተለያዩ ናቸው። ትክክለኛውን ምክንያት ለማወቅ የኩሪየር መዝገቦችን ከፍተው የኩሪየሩን ምላሽ ያንብቡ።',
'Cr_Guide_Q_City' => 'ኩሪየሩ ከተማውን ወይም አድራሻውን አይቀበልም',
'Cr_Guide_A_City' => 'በማስያዣ ቅጹ ውስጥ ከኩሪየሩ የከተሞች ዝርዝር ከተማውን ይምረጡ፤ ኩሪየሮች የሚቀበሉት የራሳቸውን ስሞች ብቻ ነው። በፖስታ አድራሻዎች የሚሰሩ ኩሪየሮች ክልሉን፣ የፖስታ ኮዱንና ባለሁለት ፊደል አገርንም ይፈልጋሉ።',
'Cr_Guide_Q_Webhook' => 'ሁኔታዎች በራሳቸው አይቀየሩም',
'Cr_Guide_A_Webhook' => 'ማሻሻያ ለሚልኩ ኩሪየሮች የWebhook URL በኩሪየሩ ዘንድ መመዝገቡን ያረጋግጡ፦ የኩሪየር መዝገቦች የተቀበሉትን እያንዳንዱን ማሻሻያ፣ ወይም አንዱ ለምን ውድቅ እንደተደረገ (ለምሳሌ የተሳሳተ ሚስጥራዊ ቁልፍ) ያሳያሉ። ሌሎች ኩሪየሮች በኩሪየር ቅንብሮች ውስጥ ባለው መርሐግብር ይፈተሻሉ፣ ሁኔታን አሁን ፈትሽ ደግሞ ወዲያውኑ ይጠይቃል።',
'Cr_Guide_Q_Stuck' => 'ጭነት የሁኔታ ፍተሻ ስህተት ያሳያል',
'Cr_Guide_A_Stuck' => 'ኩሪየሩ የመጨረሻዎቹን ፍተሻዎች አልተቀበለም፤ ምክንያቱ በጭነቱ ላይና በኩሪየር መዝገቦች ውስጥ አለ። ከተደጋጋሚ ውድቀቶች በኋላ ጭነቱ በራስ-ሰር አይፈተሽም፦ ምክንያቱን ያስተካክሉ፣ ከዚያም ሁኔታን አሁን ፈትሽ ይጠቀሙ።',
'Cr_Guide_Q_Label' => 'መለያ ምልክት ሲታተም ምንም አይከፈትም',
'Cr_Guide_A_Label' => 'አሳሽዎ ብቅ-ባይ መስኮቱን አግዶታል። ለዚህ ጣቢያ ብቅ-ባይ መስኮቶችን ይፍቀዱና እንደገና ይሞክሩ።',
'Cr_Guide_Q_Cod' => 'የCOD ክፍያ በሽያጩ ላይ አልተመዘገበም',
'Cr_Guide_A_Cod' => 'በኩሪየር ቅንብሮች ውስጥ በማድረስ ጊዜ ክፍያ ማብሪያው መብራትና መለያ መመረጥ አለበት። መለያ ከሌለ ክፍያዎች እንደተከፈሉ ብቻ ይመዘገባሉ።',
