'Tfa_Reset_Help' => ':name በይለፍ ቃሉ ብቻ ይገባል፣ ከዚያም የማረጋገጫ መተግበሪያውን እንደገና ማዘጋጀት ይችላል። ይህን የሚጠይቀው ማን እንደሆነ ካረጋገጡ በኋላ ብቻ ያድርጉ።',
'Tfa_Guide_Lead' => 'ባለሁለት ደረጃ ማረጋገጫ (2FA) ለመግቢያ ሁለተኛ ደረጃ ይጨምራል፦ ከይለፍ ቃሉ በኋላ ሰራተኞች በስልካቸው ላይ ካለ የማረጋገጫ መተግበሪያ ባለ 6 አሃዝ ኮድ ይተይባሉ። የተሰረቀ ወይም የተገመተ የይለፍ ቃል ለመግባት ከእንግዲህ በቂ አይደለም።',
'Tfa_Guide_State_Required' => 'አስገዳጅ',
'Tfa_Guide_State_Optional' => 'አይደለም — ለሁሉም አማራጭ',
'Tfa_Guide_State_Trust' => 'የታመኑ መሣሪያዎች',
'Tfa_Guide_State_Users' => '2FA ያበሩ ተጠቃሚዎች',
'Tfa_Guide_Staff_Title' => 'ለእያንዳንዱ ሰራተኛ',
'Tfa_Guide_App_Title' => 'የማረጋገጫ መተግበሪያ ይጫኑ',
'Tfa_Guide_App_Text' => 'መደበኛ ባለ 6 አሃዝ ኮዶችን (TOTP) የሚደግፍ ማንኛውም መተግበሪያ ይሰራል። ነፃ ናቸው፣ ያለ ኢንተርኔትም ይሰራሉ፦',
'Tfa_Guide_Enable_Title' => 'ከመገለጫው ያብሩት',
'Tfa_Guide_Enable_1' => 'መገለጫን (ከላይ በቀኝ ያለው የአቫታር ምናሌ) ይክፈቱና "ባለሁለት ደረጃ ማረጋገጫ" ካርዱን ያግኙ።',
'Tfa_Guide_Enable_2' => '"አብራ"ን ጠቅ ያድርጉና በአሁኑ የይለፍ ቃል ያረጋግጡ።',
'Tfa_Guide_Enable_3' => 'የQR ኮዱን በመተግበሪያው ስካን ያድርጉ፣ ወይም ከስሩ የሚታየውን ቁልፍ ይተይቡ።',
'Tfa_Guide_Enable_4' => 'ለመጨረስ መተግበሪያው የሚያሳየውን ባለ 6 አሃዝ ኮድ ያስገቡ።',
'Tfa_Guide_Open_Profile' => 'መገለጫዬን ክፈት',
'Tfa_Guide_Codes_Title' => 'የመልሶ ማግኛ ኮዶቹን ያስቀምጡ',
'Tfa_Guide_Codes_Text' => 'ልክ ከዝግጅቱ በኋላ 8 የመልሶ ማግኛ ኮዶች አንድ ጊዜ ይታያሉ። እያንዳንዱ የስልክ ኮድን አንድ ጊዜ ይተካል — ለጠፋ፣ ለተሰበረ ወይም ዳግም ለተጀመረ ስልክ። ያውርዷቸው ወይም ይቅዷቸውና ከስልኩ ርቀው ደህንነቱ በተጠበቀ ቦታ ያስቀምጧቸው።',
'Tfa_Guide_Codes_Note' => 'እያለቁ ነው? በመገለጫው ላይ ያለው "አዲስ የመልሶ ማግኛ ኮዶች" ሙሉውን ስብስብ ይተካል፤ አሮጌዎቹ መስራት ያቆማሉ።',
'Tfa_Guide_Signin_Title' => 'መግባት',
'Tfa_Guide_Signin_Text' => 'ከEmail እና ከይለፍ ቃሉ በኋላ የመግቢያ ገጹ ከመተግበሪያው የአሁኑን ኮድ ይጠይቃል። ኮዶች በየ30 ሰከንዱ ይቀየራሉ፣ እያንዳንዱም አንድ ጊዜ ይሰራል።',
'Tfa_Guide_Signin_Trust' => '"በዚህ መሣሪያ ላይ እንደገና አትጠይቅ"ን ምልክት ማድረግ በዚያ አሳሽ ላይ ኮዱን ለ:days ቀናት ይዘላል።',
'Tfa_Guide_Signin_Recovery' => 'ስልክ በእጅዎ የለም? "የመልሶ ማግኛ ኮድ ተጠቀም"ን ጠቅ ያድርጉና ከተቀመጡት ኮዶች አንዱን ይተይቡ።',
'Tfa_Guide_Admin_Title' => 'ለአስተዳዳሪዎች',
'Tfa_Guide_Require_Title' => 'አስገዳጅ ያድርጉት',
'Tfa_Guide_Require_Text' => 'በዚህ ካርድ ላይ "ባለሁለት ደረጃ ማረጋገጫን አስገዳጅ አድርግ"ን ያብሩ፣ ከዚያም መጠቀም ያለባቸውን ሚናዎች ይምረጡ — ወይም ለእያንዳንዱ ተጠቃሚ ዝርዝሩን ባዶ ይተዉት። ለማስቀመጥ አስገባን ጠቅ ያድርጉ።',
'Tfa_Guide_Require_Next' => 'ማንም አይወጣም። እስካሁን 2FA የሌላቸው ተጠቃሚዎች በሚቀጥለው መግቢያቸው ከመግባታቸው በፊት በመግቢያ ገጹ ላይ ዝግጅቱን እንዲያልፉ ይመራሉ፣ የመልሶ ማግኛ ኮዶቻቸውንም እዚያ ያያሉ።',
'Tfa_Guide_Require_Note' => 'አስገዳጅ የሆነባቸው ተጠቃሚዎች ከመገለጫቸው ሊያጠፉት አይችሉም።',
'Tfa_Guide_Trust_Title' => 'የታመኑ መሣሪያዎች',
'Tfa_Guide_Trust_Text' => '"የታመኑ መሣሪያዎችን አስታውስ" ከተሳካ መግቢያ በኋላ አሳሽ ኮዱን ለምን ያህል ጊዜ መዝለል እንደሚችል ይወስናል። እንደ የሱቅ ወለል POS ላሉ የጋራ ወይም የህዝብ ኮምፒውተሮች "ሁልጊዜ ኮድ ጠይቅ"ን ይምረጡ።',
'Tfa_Guide_Trust_Note' => 'ቁጥሩን መቀነስ አስቀድመው የታመኑ መሣሪያዎችን ጊዜ ያሳጥራል፤ 2FAን ማጥፋት ወይም ዳግም ማስጀመር ሁሉንም ይረሳቸዋል።',
'Tfa_Guide_Lost_Title' => 'የጠፋ ስልክ እና የመልሶ ማግኛ ኮዶች የሉም',
'Tfa_Guide_Lost_Text' => 'በተጠቃሚዎች ገጽ ላይ 2FA ያላቸው ተጠቃሚዎች በ2FA አምድ ውስጥ "በርቷል" ያሳያሉ። በድርጊቶች ውስጥ ያለው የጋሻ ቁልፍ ዳግም ያስጀምረዋል፦ ተጠቃሚው በይለፍ ቃሉ ብቻ ገብቶ መተግበሪያውን እንደገና ያዘጋጃል (ወይም አስገዳጅ ከሆነ እንዲያዘጋጅ ይጠየቃል)።',
'Tfa_Guide_Lost_Warn' => 'ዳግም ከማስጀመርዎ በፊት የሚጠይቀው ማን እንደሆነ ያረጋግጡ — ዳግም ማስጀመር 2FA ለዚያ መለያ የሚሰጠውን ጥበቃ ያስወግዳል።',
'Tfa_Guide_Open_Users' => 'ተጠቃሚዎችን ክፈት',
'Tfa_Guide_Mobile_Title' => 'የሞባይል መተግበሪያ እና API',
'Tfa_Guide_Mobile_Text' => 'የሞባይል መተግበሪያውና የAPI ቶከን መግቢያ ነጥቡ ተመሳሳዩን ኮድ ይጠይቃሉ። 2FA እስካሁን ላላዘጋጀ ተጠቃሚ አስገዳጅ ከሆነ ይህን ለማድረግ አንድ ጊዜ በድሩ ላይ መግባት አለበት።',
'Tfa_Guide_Protect_Title' => 'አብሮ የተሰራ ጥበቃ',
'Tfa_Guide_Protect_1' => '5 የተሳሳቱ ኮዶች ከላይ ያሉት የመቆለፊያ ቅንብሮች ምንም ቢሆኑ ለዚያ ተጠቃሚ ኮድ ማስገባትን ለ15 ደቂቃዎች ያግዳሉ።',
'Tfa_Guide_Protect_2' => 'እያንዳንዱ ኮድና እያንዳንዱ የመልሶ ማግኛ ኮድ የሚሰራው አንድ ጊዜ ብቻ ነው።',
'Tfa_Guide_Protect_3' => '"የመግቢያ እንቅስቃሴን መዝግብ" በርቶ ከሆነ የተሳሳቱ ኮዶች በመግቢያ እንቅስቃሴ ዝርዝር ውስጥ "የተሳሳተ የ2FA ኮድ" ተብለው ይታያሉ።',
'Tfa_Guide_Trouble_Title' => 'ችግር መፍቻ',
'Tfa_Guide_Faq_Clock_Q' => 'በአዲስ ኮድ “ያ ኮድ ትክክል አይደለም”',
'Tfa_Guide_Faq_Clock_A' => 'የስልኩ ሰዓት ምናልባት የተሳሳተ ነው። ኮዶች በጊዜ ላይ ይመሰረታሉ፦ የስልኩን ቀንና ሰዓት ወደ ራስ-ሰር (የኔትወርክ ሰዓት) ያዘጋጁ፣ ከዚያም ቀጣዩን ኮድ ይሞክሩ።',
'Tfa_Guide_Faq_Phone_Q' => 'ወደ አዲስ ስልክ መቀየር',
'Tfa_Guide_Faq_Phone_A' => 'የማረጋገጫ መተግበሪያውን የራሱን የማስተላለፊያ ባህሪ ይጠቀሙ፣ ወይም በመገለጫው ላይ 2FAን አጥፍተው በአዲሱ ስልክ እንደገና ያብሩት (አስገዳጅ ከሆነ በምትኩ አስተዳዳሪ ዳግም እንዲያስጀምረው ይጠይቁ)።',
'Tfa_Guide_Faq_Locked_Q' => '“በጣም ብዙ ልክ ያልሆኑ ኮዶች”',
'Tfa_Guide_Faq_Locked_A' => 'የሚታየውን ጊዜ (እስከ 15 ደቂቃዎች) ይጠብቁ፣ ወይም አስተዳዳሪ የተጠቃሚውን 2FA ዳግም እንዲያስጀምር ያድርጉ።',
'Tfa_Guide_Faq_Key_Q' => 'ከሰርቨር ዝውውር በኋላ 2FA ያለው ማንም መግባት አይችልም',
'Tfa_Guide_Faq_Key_A' => 'የ2FA ሚስጥሮች በ.env ፋይሉ ውስጥ ባለው APP_KEY ተመስጥረዋል። መተግበሪያውን ሲያዛውሩ ወይም ሲመልሱ ተመሳሳዩን APP_KEY ያቆዩ፤ ከተቀየረ 2FA የሌለው አስተዳዳሪ የተጎዱትን ተጠቃሚዎች ዳግም ማስጀመር አለበት።',
'Tfa_Guide_Button' => 'መመሪያ',
'Tfa_Guide_Title' => 'የባለሁለት ደረጃ ማረጋገጫ መመሪያ',
'Sec_2fa_Pending' => ':count ገና ማዘጋጀት አለባቸው',
'Sec_2fa_See_Who' => 'እነማን እንደሆኑ ይመልከቱ',
'Sec_2fa_Grace_Off' => 'የለም — በሚቀጥለው መግቢያ ያዘጋጁ',
'Sec_2fa_Applied' => ':count ተጠቃሚ(ዎች) ወጥተዋል።',
'Tfa_Guide_Rollout_Title' => 'ለእያንዳንዱ ተጠቃሚ ያሰራጩት',
'Tfa_Guide_Rollout_1' => 'እርምጃዎቹን እንዲያውቁ መጀመሪያ ለራስዎ መለያ ያብሩት (መገለጫ)።',
'Tfa_Guide_Rollout_2' => 'ለቡድንዎ የትኛውን መተግበሪያ እንደሚጭኑ እና ዝግጅቱ በመግቢያ ጊዜ አንድ ደቂቃ እንደሚወስድ ይንገሩ።',
'Tfa_Guide_Rollout_3' => '"ባለሁለት ደረጃ ማረጋገጫን አስገዳጅ አድርግ"ን ያብሩ፣ "የሚያስፈልገው ለ"ን ባዶ ይተዉት (= እያንዳንዱ ተጠቃሚ)፣ እና ከፈለጉ የእፎይታ ጊዜ ይምረጡ። አስገባን ጠቅ ያድርጉ።',
'Tfa_Guide_Rollout_4' => 'አስቀድመው የገቡ ሰዎች በኋላ በሆነ መግቢያ ሳይሆን አሁን እንዲያዘጋጁት "2FA የሌላቸውን ተጠቃሚዎች አስወጣ"ን ጠቅ ያድርጉ። እርስዎ እንደገቡ ይቆያሉ።',
'Tfa_Guide_Rollout_5' => 'ሂደቱን በዚህ ካርድ ላይ ባለው ቆጣሪ፣ ወይም በተጠቃሚዎች ገጽ ላይ ባለው "ዝግጅት ያስፈልገዋል" ማጣሪያ ይከታተሉ።',
'Tfa_Guide_Rollout_Note' => 'የእፎይታ ጊዜ ካለ የዝግጅት ማያው እስከ መጨረሻው ቀን ድረስ “በኋላ አስታውሰኝ”ን ያሳያል፤ ከዚያ በኋላ ለመግባት ዝግጅቱ አስገዳጅ ነው።',
'Tfa_Guide_Customers_Title' => 'የደንበኛ መለያዎች (ሱቅ እና የደንበኛ ፖርታል)',
'Tfa_Guide_Customers_Text' => 'ደንበኞችም የራሳቸውን መለያዎች መጠበቅ ይችላሉ። ለእያንዳንዱ ደንበኛ አማራጭ ነው፣ በፍጹም አይገደድም፦ በሱቅ ቅንብሮች → የምዝገባ መዳረሻ ቁጥጥር (ኦንላይን ሱቅ) እና በደንበኛ ፖርታል → የፖርታል ቅንብሮች (የደንበኛ ፖርታል) ስር ያብሩት።',
'Tfa_Guide_Customers_1' => 'ደንበኞች ከመለያዬ (ሱቅ) ወይም ከመገለጫ (ፖርታል) ያበሩታል።',
'Tfa_Guide_Customers_2' => 'በEmail የሚላክ ኮድ — በጣም ቀላሉ፣ መተግበሪያ አያስፈልገውም — ወይም የመልሶ ማግኛ ኮዶች ያሉት የማረጋገጫ መተግበሪያ ይመርጣሉ።',
'Tfa_Guide_Customers_3' => 'በEmail የሚላኩ ኮዶች የሚሰሩ የሜይል ቅንብሮች ያስፈልጋቸዋል (ቅንብሮች → የሜይል ቅንብሮች)። ከ10 ደቂቃዎች በኋላ ጊዜያቸው ያልፋል።',
'Tfa_Guide_Customers_4' => 'አማራጩን በኋላ ማጥፋት አዲስ ዝግጅቶችን ያቆማል፤ አስቀድመው የሚጠቀሙት ደንበኞች መጠየቃቸውን ይቀጥላሉ፣ ራሳቸውም ሊያጠፉት ይችላሉ።',
'Tfa_Required_Grace_Notice' => 'አስተዳዳሪዎ ባለሁለት ደረጃ ማረጋገጫን ይጠይቃል። እስከ :date ድረስ በመግቢያ ጊዜ ማዘግየት ይችላሉ፤ ከዚያ በኋላ ዝግጅቱ አስገዳጅ ነው።',
'Tfa_Filter_All' => '2FA፦ ሁሉም ተጠቃሚዎች',
'Tfa_Needs_Setup_Help' => 'በሲስተም ቅንብሮች > ደህንነት የሚያስፈልግ፤ በሚቀጥለው መግቢያ እንዲያዘጋጁት ይጠየቃሉ።',
'Tfa_Needs_Setup' => 'ዝግጅት ያስፈልገዋል',
