'Store_Customer_2fa_Help' => 'ደንበኞች መለያቸውን በEmail በሚላክ ወይም ከማረጋገጫ መተግበሪያ በሚመጣ ኮድ እንዲጠብቁ ያስችላል፣ ከመለያዬ ይበራል። ለእያንዳንዱ ደንበኛ አማራጭ ነው።',
