'Sec_2fa_Apply_Help' => 'አስቀድመው የገቡ ሰዎች የሚጠየቁት በሚቀጥለው መግቢያቸው ብቻ ነው፣ ይህም በ“አስታውሰኝ” ወራት ሊርቅ ይችላል። ይህ 2FA ማዘጋጀት ያለባቸውንና ያላዘጋጁትን ሁሉ ከእያንዳንዱ መሣሪያ ያስወጣል፣ ስለዚህ ተመልሰው ሲገቡ ያዘጋጁታል። እርስዎ እንደገቡ ይቆያሉ።',
